// ---------------------------------------------------------------------------
// Lumen Isles — game data
// All creatures, moves, types and artwork are original procedural creations.
// ---------------------------------------------------------------------------

export const TYPES = {
  normal: { name: 'Normal', color: '#b7ac95', light: '#f2ecdf' },
  leaf:   { name: 'Leaf',   color: '#54b96b', light: '#dff3d9' },
  ember:  { name: 'Ember',  color: '#ef6f3c', light: '#ffe0d1' },
  aqua:   { name: 'Aqua',   color: '#3d9fdc', light: '#d6efff' },
  spark:  { name: 'Spark',  color: '#dfa92b', light: '#fff0be' },
  stone:  { name: 'Stone',  color: '#8f8272', light: '#eee5d7' },
};

// Attacking a type in strong[attacker] deals x2. Attacking a type that is
// strong against the attacker deals x0.5.
const STRONG = {
  normal: [],
  leaf: ['aqua', 'stone'],
  ember: ['leaf'],
  aqua: ['ember', 'stone'],
  spark: ['aqua'],
  stone: ['spark', 'ember'],
};

export function typeMultiplier(attackType, defendType) {
  if (STRONG[attackType]?.includes(defendType)) return 2;
  if (STRONG[defendType]?.includes(attackType)) return 0.5;
  return 1;
}

export const MOVES = {
  tackle:   { name: 'Tackle',    type: 'normal', power: 38, accuracy: 0.96, pp: 30, desc: 'A sturdy full-body charge.' },
  scratch:  { name: 'Scratch',   type: 'normal', power: 42, accuracy: 0.94, pp: 25, desc: 'Rakes with tiny claws.' },
  leafwhip: { name: 'Leaf Whip', type: 'leaf',   power: 48, accuracy: 0.94, pp: 20, desc: 'A spinning blade of leaves.' },
  ember:    { name: 'Ember',     type: 'ember',  power: 48, accuracy: 0.92, pp: 20, desc: 'A warm burst of sparks.' },
  bubble:   { name: 'Bubble',    type: 'aqua',   power: 48, accuracy: 0.95, pp: 20, desc: 'A volley of pressurised bubbles.' },
  spark:    { name: 'Spark',     type: 'spark',  power: 46, accuracy: 0.94, pp: 20, desc: 'A crackling static zap.' },
  rocktoss: { name: 'Rock Toss', type: 'stone',  power: 52, accuracy: 0.88, pp: 15, desc: 'Hurls a heavy pebble.' },
  gust:     { name: 'Gust',      type: 'normal', power: 44, accuracy: 0.95, pp: 20, desc: 'A buffeting flap of wings.' },
  bite:     { name: 'Bite',      type: 'normal', power: 50, accuracy: 0.9,  pp: 20, desc: 'A surprisingly toothy nibble.' },
  growl:    { name: 'Growl',     type: 'normal', power: 0,  accuracy: 1,    pp: 20, effect: 'atkDown', desc: 'A tiny roar. Lowers Attack.' },
  harden:   { name: 'Harden',    type: 'stone',  power: 0,  accuracy: 1,    pp: 20, effect: 'defUp', desc: 'Tenses up. Raises Defense.' },
  pollen:   { name: 'Pollen Puff', type: 'leaf', power: 0,  accuracy: 0.95, pp: 15, effect: 'drain', desc: 'Steals a little vitality.' },
  moonbeam: { name: 'Moonbeam',  type: 'normal', power: 58, accuracy: 0.9,  pp: 10, desc: 'A focused beam of pale light.' },
  antler:   { name: 'Antler Rush', type: 'leaf', power: 60, accuracy: 0.92, pp: 10, desc: 'A guardian charge.' },
  stomp:    { name: 'Stomp',     type: 'normal', power: 55, accuracy: 0.9,  pp: 15, desc: 'A ground-shaking stomp.' },
};

export const SPECIES = {
  spriglet: {
    name: 'Spriglet', type: 'leaf', model: 'spriglet',
    base: { hp: 52, atk: 15, def: 15, spd: 16 },
    catch: 0.62, scale: 0.95,
    lore: 'A curious leaf-fox. Its tail sprouts anew every spring.',
    moves: [[1, 'tackle'], [1, 'leafwhip'], [8, 'growl'], [13, 'pollen']],
  },
  emberpup: {
    name: 'Emberpup', type: 'ember', model: 'emberpup',
    base: { hp: 50, atk: 18, def: 13, spd: 17 },
    catch: 0.62, scale: 0.95,
    lore: 'The ember on its tail burns brighter when it is happy.',
    moves: [[1, 'scratch'], [1, 'ember'], [8, 'growl'], [13, 'bite']],
  },
  dropplet: {
    name: 'Dropplet', type: 'aqua', model: 'dropplet',
    base: { hp: 56, atk: 14, def: 17, spd: 14 },
    catch: 0.62, scale: 0.95,
    lore: 'A river otter that keeps pebbles as tiny treasures.',
    moves: [[1, 'tackle'], [1, 'bubble'], [8, 'harden'], [13, 'bite']],
  },
  mossling: {
    name: 'Mossling', type: 'leaf', model: 'mossling',
    base: { hp: 44, atk: 13, def: 12, spd: 19 },
    catch: 0.72, scale: 0.85,
    lore: 'Mossling naps in the sun and photosynthesises its lunch.',
    moves: [[1, 'tackle'], [1, 'pollen'], [7, 'growl']],
  },
  pebblit: {
    name: 'Pebblit', type: 'stone', model: 'pebblit',
    base: { hp: 60, atk: 17, def: 22, spd: 8 },
    catch: 0.66, scale: 0.9,
    lore: 'It pretends to be a rock, badly. Moss loves it anyway.',
    moves: [[1, 'tackle'], [1, 'rocktoss'], [8, 'harden']],
  },
  zapmouse: {
    name: 'Zapmouse', type: 'spark', model: 'zapmouse',
    base: { hp: 46, atk: 18, def: 12, spd: 22 },
    catch: 0.6, scale: 0.85,
    lore: 'Its zig-zag tail stores just enough charge for one big zap.',
    moves: [[1, 'scratch'], [1, 'spark'], [8, 'growl']],
  },
  fluffbat: {
    name: 'Fluffbat', type: 'normal', model: 'fluffbat',
    base: { hp: 46, atk: 16, def: 12, spd: 21 },
    catch: 0.64, scale: 0.8,
    lore: 'Fluffbat is mostly fluff, but it flies with tremendous pride.',
    moves: [[1, 'gust'], [1, 'bite'], [8, 'growl']],
  },
  elderwood: {
    name: 'Elderwood', type: 'leaf', model: 'elderwood',
    base: { hp: 96, atk: 23, def: 21, spd: 15 },
    catch: 0.04, scale: 1.0, boss: true,
    lore: 'The grove remembers. The grove protects.',
    moves: [[1, 'antler'], [1, 'stomp'], [10, 'harden'], [12, 'moonbeam']],
  },
};

export const XP_TO_NEXT = (level) => Math.round(22 + level * level * 2.6);

export const MAX_LEVEL = 30;

export function statsFor(speciesId, level) {
  const base = SPECIES[speciesId].base;
  return {
    maxHp: Math.round(base.hp * 0.55 + level * 4.2),
    atk: Math.round(base.atk * 0.7 + level * 1.1),
    def: Math.round(base.def * 0.7 + level * 1.0),
    spd: Math.round(base.spd * 0.7 + level * 0.9),
  };
}

let nextUid = 1;

export function createCreature(speciesId, level, opts = {}) {
  const species = SPECIES[speciesId];
  const stats = statsFor(speciesId, level);
  const learned = species.moves.filter(([lvl]) => lvl <= level);
  while (learned.length < 2) learned.push(species.moves[learned.length]);
  const moves = learned.slice(-4).map(([, id]) => ({
    id,
    pp: MOVES[id].pp,
    maxPp: MOVES[id].pp,
  }));
  return {
    uid: nextUid++,
    species: speciesId,
    level,
    exp: 0,
    hp: stats.maxHp,
    ...stats,
    atkStage: 0,
    defStage: 0,
    moves,
    shiny: opts.shiny ?? Math.random() < 0.035,
    nickname: null,
  };
}

export function displayName(mon) {
  return mon.nickname || SPECIES[mon.species].name;
}

export function healCreature(mon) {
  mon.hp = mon.maxHp;
  mon.atkStage = 0;
  mon.defStage = 0;
  for (const m of mon.moves) m.pp = m.maxPp;
}

export function stageMultiplier(stage) {
  return Math.max(0.4, 1 + stage * 0.33);
}

export function xpGain(defeated, isBoss = false) {
  const base = 16 + defeated.level * 6 + (isBoss ? 70 : 0);
  return Math.round(base);
}

export function levelUp(mon) {
  if (mon.level >= MAX_LEVEL) return null;
  const old = statsFor(mon.species, mon.level);
  mon.level += 1;
  const next = statsFor(mon.species, mon.level);
  mon.maxHp = next.maxHp;
  mon.atk = next.atk;
  mon.def = next.def;
  mon.spd = next.spd;
  mon.hp = Math.min(mon.maxHp, mon.hp + (next.maxHp - old.maxHp));
  const learned = [];
  for (const [lvl, moveId] of SPECIES[mon.species].moves) {
    if (lvl === mon.level) {
      if (mon.moves.length < 4) {
        mon.moves.push({ id: moveId, pp: MOVES[moveId].pp, maxPp: MOVES[moveId].pp });
        learned.push(moveId);
      } else {
        const weakest = mon.moves[0];
        mon.moves.shift();
        mon.moves.push({ id: moveId, pp: MOVES[moveId].pp, maxPp: MOVES[moveId].pp });
        learned.push(moveId);
      }
    }
  }
  return { learned };
}

export function starterOptions() {
  return ['spriglet', 'emberpup', 'dropplet'];
}

import * as THREE from '../vendor/three.module.js';

// ---------------------------------------------------------------------------
// Procedural low-poly character and creature models
// ---------------------------------------------------------------------------

const materials = new Map();

export function material(color, options = {}) {
  const key = color + JSON.stringify(options);
  if (!materials.has(key)) {
    materials.set(key, new THREE.MeshStandardMaterial({
      color,
      roughness: 0.82,
      metalness: 0,
      flatShading: true,
      ...options,
    }));
  }
  return materials.get(key);
}

const geo = {
  sphere: new THREE.SphereGeometry(1, 14, 11),
  sphereLow: new THREE.SphereGeometry(1, 8, 6),
  cone: new THREE.ConeGeometry(1, 1, 7),
  cyl: new THREE.CylinderGeometry(1, 1, 1, 7),
  box: new THREE.BoxGeometry(1, 1, 1),
  dodeca: new THREE.DodecahedronGeometry(1, 0),
  octa: new THREE.OctahedronGeometry(1, 0),
  circle: new THREE.CircleGeometry(1, 20),
  torus: new THREE.TorusGeometry(1, 0.08, 6, 24),
};

function add(parent, geometry, color, position = [0, 0, 0], scale = [1, 1, 1], rotation = [0, 0, 0], options) {
  const m = new THREE.Mesh(geometry, material(color, options));
  m.position.set(...position);
  m.scale.set(...scale);
  m.rotation.set(...rotation);
  m.castShadow = true;
  m.receiveShadow = true;
  parent.add(m);
  return m;
}

function eyePair(parent, y, z, spread, size = 0.085, headScale = 1) {
  const eyes = [];
  for (const side of [-1, 1]) {
    const white = add(parent, geo.sphere, '#fffdf2', [side * spread, y, z], [size, size * 1.12, size * 0.6]);
    white.castShadow = false;
    const pupil = add(parent, geo.sphereLow, '#2e2833', [side * spread, y - 0.005, z + size * 0.6], [size * 0.5, size * 0.72, size * 0.3]);
    pupil.castShadow = false;
    const glint = add(parent, geo.sphereLow, '#ffffff', [side * spread + size * 0.22, y + size * 0.35, z + size * 0.82], [size * 0.18, size * 0.18, size * 0.1]);
    glint.castShadow = false;
    eyes.push(white, pupil);
  }
  return eyes;
}

function cheekPair(parent, y, z, spread, color = '#f28c8c') {
  for (const side of [-1, 1]) {
    const c = add(parent, geo.sphereLow, color, [side * spread, y, z], [0.075, 0.045, 0.02]);
    c.castShadow = false;
  }
}

function shadowBlob(size = 1) {
  const m = new THREE.Mesh(
    geo.circle,
    new THREE.MeshBasicMaterial({ color: '#22301f', transparent: true, opacity: 0.24, depthWrite: false }),
  );
  m.rotation.x = -Math.PI / 2;
  m.position.y = 0.02;
  m.scale.setScalar(size);
  m.renderOrder = 2;
  return m;
}

function leafShape(color, position, rotation, scale) {
  const m = new THREE.Mesh(geo.octa, material(color));
  m.position.set(...position);
  m.rotation.set(...rotation);
  m.scale.set(...scale);
  m.castShadow = true;
  return m;
}

// ---------------------------------------------------------------------------
// Creatures
// ---------------------------------------------------------------------------

function buildSpriglet() {
  const g = new THREE.Group();
  const body = new THREE.Group();
  g.add(body);
  add(body, geo.sphere, '#7ed06d', [0, 0.58, 0], [0.42, 0.46, 0.4]);
  add(body, geo.sphere, '#eaf7bd', [0, 0.5, 0.24], [0.28, 0.3, 0.2]);
  const head = new THREE.Group();
  head.position.set(0, 1.02, 0.04);
  body.add(head);
  add(head, geo.sphere, '#7ed06d', [0, 0, 0], [0.36, 0.34, 0.34]);
  add(head, geo.sphere, '#f1f8cc', [0, -0.08, 0.25], [0.2, 0.14, 0.16]);
  add(head, geo.sphereLow, '#4a8f43', [0, -0.02, 0.38], [0.05, 0.035, 0.03]);

  const ears = [];
  for (const side of [-1, 1]) {
    const ear = add(head, geo.cone, '#6cc25c', [side * 0.23, 0.32, -0.02], [0.12, 0.38, 0.09], [0, 0, side * 0.28]);
    const inner = add(head, geo.cone, '#f2b9a0', [side * 0.22, 0.31, 0.02], [0.065, 0.23, 0.05], [0, 0, side * 0.28]);
    inner.castShadow = false;
    ears.push(ear);
  }
  add(head, geo.sphere, '#5eae4f', [0, 0.2, -0.18], [0.2, 0.25, 0.14]);
  const leaf = leafShape('#4c9a48', [0.07, 0.42, -0.08], [0.2, 0.3, -0.5], [0.16, 0.09, 0.28]);
  head.add(leaf);
  eyePair(head, 0.05, 0.26, 0.145);
  cheekPair(head, -0.04, 0.27, 0.23, '#f3a6a0');

  const tail = new THREE.Group();
  tail.position.set(0, 0.7, -0.35);
  body.add(tail);
  const tl = leafShape('#4f9c49', [0, 0.08, -0.2], [0.3, 0.2, 0], [0.22, 0.13, 0.5]);
  tail.add(tl);
  const tl2 = leafShape('#62b258', [0.12, 0.2, -0.26], [0.15, 0.1, 0.6], [0.16, 0.1, 0.34]);
  tail.add(tl2);

  const legs = [];
  for (const side of [-1, 1]) {
    const leg = add(body, geo.sphere, '#5fae50', [side * 0.2, 0.16, 0.04], [0.11, 0.15, 0.13]);
    legs.push(leg);
    add(body, geo.sphere, '#f2f6d0', [side * 0.2, 0.1, 0.13], [0.09, 0.06, 0.08]);
  }
  for (const side of [-1, 1]) {
    add(body, geo.sphere, '#7ed06d', [side * 0.39, 0.62, 0.06], [0.1, 0.19, 0.1]);
  }

  g.userData.anim = { body, head, ears, tail: [tail], leaf, bodyY: 0 };
  return g;
}

function buildEmberpup() {
  const g = new THREE.Group();
  const body = new THREE.Group();
  g.add(body);
  add(body, geo.sphere, '#ee844e', [0, 0.6, 0], [0.43, 0.48, 0.4]);
  add(body, geo.sphere, '#ffe0b0', [0, 0.5, 0.25], [0.27, 0.3, 0.2]);
  const head = new THREE.Group();
  head.position.set(0, 1.06, 0.06);
  body.add(head);
  add(head, geo.sphere, '#f08b52', [0, 0, 0], [0.36, 0.34, 0.35]);
  add(head, geo.sphere, '#ffe3b8', [0, -0.09, 0.27], [0.22, 0.17, 0.18]);
  add(head, geo.sphereLow, '#432f32', [0, 0.005, 0.44], [0.06, 0.045, 0.03]);
  add(head, geo.sphereLow, '#ffe3b8', [0, 0.12, 0.4], [0.05, 0.04, 0.03]);

  const ears = [];
  for (const side of [-1, 1]) {
    const ear = add(head, geo.sphere, '#d96a3c', [side * 0.27, 0.15, -0.02], [0.12, 0.29, 0.08], [0.2, 0, side * 0.62]);
    const tip = add(head, geo.sphere, '#7d3c2a', [side * 0.36, 0.31, 0.0], [0.075, 0.12, 0.055], [0.2, 0, side * 0.62]);
    tip.castShadow = false;
    ears.push(ear);
  }
  eyePair(head, 0.04, 0.27, 0.145);
  cheekPair(head, -0.04, 0.29, 0.24, '#f4a58b');

  const tail = new THREE.Group();
  tail.position.set(0, 0.74, -0.36);
  body.add(tail);
  add(tail, geo.sphere, '#d96a3c', [0, 0.02, -0.16], [0.13, 0.15, 0.2]);
  add(tail, geo.cone, '#ffb43f', [0, 0.22, -0.22], [0.15, 0.4, 0.15], [-0.5, 0, 0], { emissive: '#ff7a1a', emissiveIntensity: 0.35 });
  add(tail, geo.cone, '#ffd56b', [0.02, 0.28, -0.21], [0.085, 0.28, 0.085], [-0.55, 0, 0], { emissive: '#ffb43f', emissiveIntensity: 0.5 });

  for (const side of [-1, 1]) {
    add(body, geo.sphere, '#ee844e', [side * 0.2, 0.15, 0.05], [0.11, 0.15, 0.13]);
    add(body, geo.sphere, '#ffe0b0', [side * 0.2, 0.09, 0.14], [0.09, 0.06, 0.08]);
    add(body, geo.sphere, '#f08b52', [side * 0.4, 0.64, 0.06], [0.1, 0.19, 0.1]);
  }

  g.userData.anim = { body, head, ears, tail: [tail], bodyY: 0 };
  return g;
}

function buildDropplet() {
  const g = new THREE.Group();
  const body = new THREE.Group();
  g.add(body);
  add(body, geo.sphere, '#63c3e2', [0, 0.58, 0], [0.44, 0.47, 0.4]);
  add(body, geo.sphere, '#dff7fc', [0, 0.5, 0.26], [0.29, 0.31, 0.18]);
  const head = new THREE.Group();
  head.position.set(0, 1.06, 0.08);
  body.add(head);
  add(head, geo.sphere, '#6ecae6', [0, 0, 0], [0.37, 0.34, 0.34]);
  add(head, geo.sphere, '#eafcff', [0, -0.08, 0.28], [0.23, 0.16, 0.17]);
  add(head, geo.sphereLow, '#28576b', [0, 0.05, 0.43], [0.065, 0.05, 0.03]);
  add(head, geo.sphereLow, '#3e8ea4', [-0.1, -0.03, 0.42], [0.03, 0.02, 0.02]);
  add(head, geo.sphereLow, '#3e8ea4', [0.1, -0.03, 0.42], [0.03, 0.02, 0.02]);
  eyePair(head, 0.04, 0.27, 0.145);

  for (const side of [-1, 1]) {
    add(head, geo.sphere, '#57b7d6', [side * 0.3, 0.18, -0.03], [0.09, 0.11, 0.06]);
    add(head, geo.sphereLow, '#2f7f99', [side * 0.36, 0.3, -0.01], [0.08, 0.07, 0.05]);
    add(body, geo.sphere, '#63c3e2', [side * 0.4, 0.63, 0.04], [0.1, 0.18, 0.1]);
    add(body, geo.sphere, '#63c3e2', [side * 0.21, 0.14, 0.05], [0.11, 0.14, 0.13]);
  }

  const tail = new THREE.Group();
  tail.position.set(0, 0.63, -0.4);
  body.add(tail);
  add(tail, geo.sphere, '#4fb6d6', [0, -0.04, -0.12], [0.13, 0.09, 0.3]);
  add(tail, geo.sphere, '#8ee0f2', [0, 0.01, -0.31], [0.2, 0.06, 0.2]);

  g.userData.anim = { body, head, tail: [tail], bodyY: 0 };
  return g;
}

function buildMossling() {
  const g = new THREE.Group();
  const body = new THREE.Group();
  g.add(body);
  add(body, geo.sphere, '#9fce6f', [0, 0.45, 0], [0.46, 0.44, 0.42]);
  add(body, geo.sphere, '#d9efaa', [0, 0.38, 0.24], [0.3, 0.26, 0.18]);
  add(body, geo.sphere, '#7cad4e', [0, 0.72, -0.08], [0.36, 0.16, 0.31]);
  const head = new THREE.Group();
  head.position.set(0, 0.72, 0.06);
  body.add(head);
  add(head, geo.sphere, '#b3d982', [0, 0, 0.14], [0.28, 0.25, 0.18]);
  add(head, geo.sphereLow, '#375030', [0, -0.02, 0.34], [0.05, 0.03, 0.03]);
  eyePair(head, 0.03, 0.32, 0.12, 0.065);
  cheekPair(head, -0.06, 0.34, 0.19, '#edb4a6');

  const sprout = new THREE.Group();
  sprout.position.set(-0.02, 0.24, 0.04);
  head.add(sprout);
  add(sprout, geo.cyl, '#6b9a3d', [0, 0.1, 0], [0.022, 0.22, 0.022]);
  sprout.add(leafShape('#7db84e', [-0.09, 0.23, 0], [0, 0, -0.6], [0.16, 0.04, 0.09]));
  sprout.add(leafShape('#8fcb5f', [0.1, 0.26, 0], [0, 0, 0.6], [0.16, 0.04, 0.09]));

  const sprout2 = sprout.clone();
  sprout2.position.set(0.13, 0.2, -0.12);
  sprout2.scale.setScalar(0.7);
  head.add(sprout2);

  for (const side of [-1, 1]) {
    add(body, geo.sphere, '#8dbb5e', [side * 0.2, 0.09, 0.08], [0.13, 0.08, 0.15]);
  }

  g.userData.anim = { body, head, tail: [sprout], bodyY: 0 };
  return g;
}

function buildPebblit() {
  const g = new THREE.Group();
  const body = new THREE.Group();
  g.add(body);
  add(body, geo.dodeca, '#9b958b', [0, 0.48, 0], [0.47, 0.44, 0.43]);
  add(body, geo.dodeca, '#b2aca1', [0.08, 0.34, 0.18], [0.28, 0.25, 0.2]);
  add(body, geo.sphere, '#7fae5c', [-0.12, 0.73, -0.1], [0.28, 0.12, 0.25]);
  add(body, geo.sphere, '#8fbe68', [0.14, 0.66, -0.18], [0.18, 0.09, 0.17]);
  const head = new THREE.Group();
  head.position.set(0, 0.66, 0.2);
  body.add(head);
  add(head, geo.sphereLow, '#a7a096', [0, 0, 0], [0.34, 0.26, 0.24]);
  eyePair(head, 0.03, 0.22, 0.14, 0.075);
  add(head, geo.sphereLow, '#544a44', [0, -0.08, 0.24], [0.06, 0.025, 0.02]);
  cheekPair(head, -0.05, 0.24, 0.2, '#c7a69a');

  const arms = [];
  for (const side of [-1, 1]) {
    const arm = new THREE.Group();
    arm.position.set(side * 0.47, 0.56, 0.04);
    body.add(arm);
    add(arm, geo.dodeca, '#8f887d', [0, -0.03, 0], [0.15, 0.2, 0.14]);
