const BUILDERS = {
  spriglet: buildSpriglet,
  emberpup: buildEmberpup,
  dropplet: buildDropplet,
  mossling: buildMossling,
  pebblit: buildPebblit,
  zapmouse: buildZapmouse,
  fluffbat: buildFluffbat,
  elderwood: buildElderwood,
};

export function buildCreature(speciesId) {
  const builder = BUILDERS[speciesId] || buildSpriglet;
  const g = builder();
  g.traverse((o) => {
    if (o.isMesh) {
      o.castShadow = true;
      o.receiveShadow = true;
    }
  });
  if (speciesId === 'elderwood') {
    g.scale.setScalar(1.15);
  }
  g.userData.speciesId = speciesId;
  return g;
}

export function animateCreature(g, time, excitement = 0) {
  const a = g.userData.anim;
  if (!a) return;
  const speed = 2.3 + excitement;
  const breathe = Math.sin(time * speed) * 0.025;
  if (a.body) a.body.position.y = (a.bodyY || 0) + breathe;
  if (a.head) {
    a.head.rotation.z = Math.sin(time * speed * 0.7) * 0.045;
    a.head.rotation.x = Math.cos(time * speed * 0.43) * 0.025;
  }
  if (a.ears) {
    a.ears.forEach((ear, i) => {
      ear.rotation.x = Math.sin(time * speed * 1.25 + i) * 0.1;
    });
  }
  if (a.tail) {
    a.tail.forEach((tail, i) => {
      tail.rotation.y = Math.sin(time * speed * 0.9 + i * 0.8) * 0.16;
      tail.rotation.x = Math.sin(time * speed * 0.5 + i) * 0.05;
    });
  }
  if (a.wings) {
    a.wings.forEach((wing, i) => {
      wing.rotation.z = (i === 0 ? 1 : -1) * (0.18 + Math.sin(time * speed * 2.2) * 0.35);
    });
  }
  if (a.arms) {
    a.arms.forEach((arm, i) => {
      arm.position.y = 0.56 + Math.sin(time * speed * 0.8 + i) * 0.03;
    });
  }
  if (a.glow) {
    a.glow.forEach((orb, i) => {
      orb.material.emissiveIntensity = 1.8 + Math.sin(time * 2 + i) * 0.7;
      orb.position.y += Math.sin(time * 1.7 + i) * 0.0007;
    });
  }
  if (a.leaf) {
    a.leaf.rotation.z = -0.5 + Math.sin(time * 1.8) * 0.12;
  }
}

