export function animateTrainer(g, time, walkAmount, jumping) {
  const a = g.userData.anim;
  if (!a) return;
  const t = time * (7 + walkAmount * 7);
  const swing = Math.sin(t) * walkAmount * 0.7;
  a.legL.rotation.x = swing;
  a.legR.rotation.x = -swing;
  a.armL.rotation.x = -swing * 0.7;
  a.armR.rotation.x = swing * 0.7;
  a.body.position.y = Math.abs(Math.sin(t)) * walkAmount * 0.05 + (jumping ? 0 : 0);
  a.body.rotation.z = Math.sin(t) * walkAmount * 0.03;
  a.head.rotation.y = Math.sin(time * 0.7) * 0.06;
}

