    for (let i = 0; i < 3; i++) {
      const vine = new THREE.Mesh(new THREE.SphereGeometry(0.4, 6, 5), material('#6f9e56'));
      vine.position.set(side * 2.4 + (rand() - 0.5) * 0.5, 1 + i * 1.1, -1.1 + (rand() - 0.5) * 0.5);
      vine.scale.set(0.6, 1.2, 0.5);
      shrine.add(vine);
    }
  }
  const lintel = new THREE.Mesh(new THREE.BoxGeometry(6.2, 0.6, 1.3), material('#98a28c'));
  lintel.position.set(0, 5.55, -1.1);
  lintel.rotation.z = 0.015;
  lintel.castShadow = true;
  shrine.add(lintel);
  const crystalMat = new THREE.MeshStandardMaterial({ color: '#c7ffc0', emissive: '#6dff8a', emissiveIntensity: 1.8, roughness: 0.25, flatShading: true });
  const crystals = [];
  for (let i = 0; i < 5; i++) {
    const crystal = new THREE.Mesh(new THREE.OctahedronGeometry(0.28 + rand() * 0.2, 0), crystalMat);
    crystal.position.set((rand() - 0.5) * 5, 5.9 + rand() * 0.8, -1.1 + (rand() - 0.5) * 0.5);
    crystal.rotation.set(rand(), rand(), rand());
    shrine.add(crystal);
    crystals.push(crystal);
  }
  const beam = new THREE.Mesh(
    new THREE.CylinderGeometry(1.2, 3.2, 26, 18, 1, true),
    new THREE.MeshBasicMaterial({ color: '#9dffb0', transparent: true, opacity: 0, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending }),
  );
  beam.position.y = 13;
  shrine.add(beam);
  group.add(shrine);
  colliders.push({ x: SHRINE.x - 2.4, z: SHRINE.z - 1.1, r: 0.85 }, { x: SHRINE.x + 2.4, z: SHRINE.z - 1.1, r: 0.85 });

  let bossGlow = 0;
  const setGuardianBeam = (on) => { bossGlow = on ? 1 : 0; };
  animated.push((dt, t) => {
    crystals.forEach((c, i) => {
      c.rotation.y += dt * 0.5;
      c.position.y += Math.sin(t * 1.3 + i) * 0.0015;
    });
    circle.rotation.z += dt * 0.12;
    runeMat.opacity = 0.45 + Math.sin(t * 2) * 0.18 + bossGlow * 0.3;
    const targetOpacity = bossGlow ? 0.15 + Math.sin(t * 1.6) * 0.05 : 0;
    beam.material.opacity += (targetOpacity - beam.material.opacity) * 0.04;
    beam.rotation.y += dt * 0.3;
  });

  // ---- clouds -------------------------------------------------------------
  const cloudMat = new THREE.MeshStandardMaterial({ color: '#fff7e8', roughness: 1, transparent: true, opacity: 0.9, flatShading: true, fog: false });
  const clouds = [];
  for (let i = 0; i < 14; i++) {
    const cloud = new THREE.Group();
    const parts = 4 + Math.floor(rand() * 4);
    for (let j = 0; j < parts; j++) {
      const puff = new THREE.Mesh(new THREE.SphereGeometry(2.2 + rand() * 2.4, 7, 5), cloudMat);
      puff.position.set((j - parts / 2) * 2.6 + (rand() - 0.5) * 2, (rand() - 0.5) * 1.2, (rand() - 0.5) * 2.4);
      puff.scale.y = 0.55;
      cloud.add(puff);
    }
    cloud.position.set((rand() - 0.5) * 310, 30 + rand() * 22, (rand() - 0.5) * 310);
    cloud.scale.setScalar(0.8 + rand() * 1.1);
    group.add(cloud);
    clouds.push(cloud);
  }
  animated.push((dt) => {
    clouds.forEach((c) => {
      c.position.x += dt * 0.55;
      if (c.position.x > 165) c.position.x = -165;
    });
  });

  // ---- pollen / fireflies ------------------------------------------------
  const pollenCount = 220;
  const pollenGeo = new THREE.BufferGeometry();
  const pollenPos = new Float32Array(pollenCount * 3);
  const pollenSeeds = [];
  for (let i = 0; i < pollenCount; i++) {
    const a = rand() * Math.PI * 2, r = Math.sqrt(rand()) * 85;
    const x = Math.cos(a) * r, z = Math.sin(a) * r;
    pollenPos[i * 3] = x;
    pollenPos[i * 3 + 1] = heightAt(x, z) + 0.5 + rand() * 5;
    pollenPos[i * 3 + 2] = z;
    pollenSeeds.push({ phase: rand() * Math.PI * 2, speed: 0.3 + rand() * 0.6, radius: 1 + rand() * 2 });
  }
  pollenGeo.setAttribute('position', new THREE.BufferAttribute(pollenPos, 3));
  const pollen = new THREE.Points(pollenGeo, new THREE.PointsMaterial({ color: '#ffefb8', size: 0.14, transparent: true, opacity: 0.72, depthWrite: false, sizeAttenuation: true }));
  group.add(pollen);
  animated.push((dt, t) => {
    const p = pollenGeo.attributes.position;
    for (let i = 0; i < pollenCount; i++) {
      const s = pollenSeeds[i];
      const baseX = pollenPos[i * 3], baseZ = pollenPos[i * 3 + 2];
      p.setX(i, baseX + Math.sin(t * s.speed + s.phase) * s.radius);
      p.setY(i, pollenPos[i * 3 + 1] + Math.sin(t * s.speed * 0.7 + s.phase) * 0.8);
      p.setZ(i, baseZ + Math.cos(t * s.speed * 0.8 + s.phase) * s.radius);
    }
    p.needsUpdate = true;
    pollen.material.opacity = 0.5 + Math.sin(t * 0.5) * 0.2;
  });

  // ---- butterflies -------------------------------------------------------
  const butterflies = [];
  const bColors = ['#ffd05c', '#ff9cc0', '#9cd8ff', '#f6f1d8'];
  for (let i = 0; i < 10; i++) {
    const b = new THREE.Group();
    const wingMat = new THREE.MeshBasicMaterial({ color: bColors[i % bColors.length], side: THREE.DoubleSide, transparent: true, opacity: 0.92 });
    for (const side of [-1, 1]) {
      const wing = new THREE.Mesh(new THREE.CircleGeometry(0.16, 6), wingMat);
      wing.position.x = side * 0.14;
      wing.scale.set(1, 0.65, 1);
      b.add(wing);
      wing.userData.side = side;
    }
    const [cx, cz] = grassPatchCenters[i % grassPatchCenters.length];
    b.userData.home = new THREE.Vector3(cx + (rand() - 0.5) * 4, heightAt(cx, cz) + 1 + rand() * 1.4, cz + (rand() - 0.5) * 4);
    b.position.copy(b.userData.home);
    b.userData.phase = rand() * Math.PI * 2;
    group.add(b);
    butterflies.push(b);
  }
  animated.push((dt, t) => {
    butterflies.forEach((b) => {
      const h = b.userData.home;
      b.position.set(
        h.x + Math.sin(t * 0.6 + b.userData.phase) * 2.4,
        heightAt(h.x, h.z) + 1.1 + Math.sin(t * 1.7 + b.userData.phase) * 0.5,
        h.z + Math.cos(t * 0.45 + b.userData.phase) * 2.4,
      );
      b.rotation.y = t * 0.6 + b.userData.phase;
      const flap = Math.sin(t * 14 + b.userData.phase) * 0.9;
      b.children.forEach((w) => { w.rotation.y = w.userData.side * (0.3 + flap); });
    });
  });

  // ---- sparkle pickups ----------------------------------------------------
  const pickups = [];
  const pickupSpots = [
    [5, -18], [-20, 6], [26, -6], [-9, 40], [44, 22], [-46, 8],
    [16, -42], [-24, -24], [52, -4], [-36, 44], [4, 56], [-54, -18],
  ];
  for (let i = 0; i < pickupSpots.length; i++) {
    const [x, z] = pickupSpots[i];
    const g = new THREE.Group();
    const y = heightAt(x, z);
    const shard = new THREE.Mesh(
      new THREE.OctahedronGeometry(0.3, 0),
      new THREE.MeshStandardMaterial({ color: i % 3 === 0 ? '#ffd86a' : '#a6f4ff', emissive: i % 3 === 0 ? '#ffb62e' : '#4fd8ff', emissiveIntensity: 1.6, roughness: 0.2, flatShading: true }),
    );
    shard.castShadow = true;
    g.add(shard);
    const ring = new THREE.Mesh(new THREE.RingGeometry(0.42, 0.54, 20), new THREE.MeshBasicMaterial({ color: '#ffe9a0', transparent: true, opacity: 0.45, side: THREE.DoubleSide, depthWrite: false }));
    ring.rotation.x = -Math.PI / 2;
    ring.position.y = -0.05;
    g.add(ring);
    g.position.set(x, y + 1.0, z);
    g.userData = { kind: i % 4 === 0 ? 'potion' : 'orb', phase: rand() * Math.PI * 2, baseY: y + 1.0, taken: false };
    group.add(g);
    pickups.push(g);
    animated.push((dt, t) => {
      g.rotation.y += dt * 1.5;
      shard.position.y = Math.sin(t * 2 + g.userData.phase) * 0.16;
      ring.rotation.z += dt * 0.7;
      g.visible = !g.userData.taken;
    });
  }

  // ---- sky dome -----------------------------------------------------------
  const skyUni = {
    uTop: { value: new THREE.Color('#4fb5d9') },
    uBottom: { value: new THREE.Color('#ffe6b3') },
    uSun: { value: new THREE.Vector3(-0.55, 0.45, -0.5).normalize() },
  };
  const sky = new THREE.Mesh(
    new THREE.SphereGeometry(480, 32, 20),
    new THREE.ShaderMaterial({
      uniforms: skyUni,
      side: THREE.BackSide,
      depthWrite: false,
      vertexShader: /* glsl */`
        varying vec3 vDir;
        void main() {
          vDir = normalize(position);
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: /* glsl */`
        uniform vec3 uTop;
        uniform vec3 uBottom;
        uniform vec3 uSun;
        varying vec3 vDir;
        void main() {
          float h = clamp(vDir.y * 1.15 + 0.06, 0.0, 1.0);
          vec3 col = mix(uBottom, uTop, pow(h, 0.68));
          float sun = max(dot(normalize(vDir), normalize(uSun)), 0.0);
          col += vec3(1.0, 0.82, 0.55) * pow(sun, 22.0) * 0.66;
          col += vec3(1.0, 0.9, 0.7) * pow(sun, 4.0) * 0.09;
          gl_FragColor = vec4(col, 1.0);
        }
      `,
    }),
  );
  sky.frustumCulled = false;
  group.add(sky);

  return {
    group,
    heightAt,
    colliders,
    pondWater,
    pickups,
    campPos: new THREE.Vector3(CAMP.x, heightAt(CAMP.x, CAMP.z), CAMP.z),
    hutPos: new THREE.Vector3(HUT.x, heightAt(HUT.x, HUT.z), HUT.z),
    shrinePos: new THREE.Vector3(SHRINE.x, heightAt(SHRINE.x, SHRINE.z), SHRINE.z),
    setGuardianBeam,
    wildSpawns: [
      { species: 'mossling', x: -15, z: -4, level: 4 },
      { species: 'zapmouse', x: 17, z: 8, level: 5 },
      { species: 'pebblit', x: 27, z: 20, level: 5 },
      { species: 'dropplet', x: 43, z: 31, level: 6 },
      { species: 'fluffbat', x: -31, z: -15, level: 5 },
      { species: 'emberpup', x: -7, z: -31, level: 6 },
      { species: 'spriglet', x: 47, z: 7, level: 6 },
      { species: 'mossling', x: 7, z: 36, level: 4 },
      { species: 'zapmouse', x: -38, z: 26, level: 7 },
      { species: 'pebblit', x: -22, z: -39, level: 6 },
      { species: 'fluffbat', x: 31, z: -35, level: 7 },
      { species: 'dropplet', x: 26, z: 47, level: 7 },
    ],
    update(dt, t) {
      for (const fn of animated) fn(dt, t);
      // keep pond water level low enough to see shore
      pondWater.position.y = 0.32 + Math.sin(t * 0.8) * 0.015;
    },
    collectPickup(p) {
      if (p.userData.taken) return null;
      p.userData.taken = true;
      return p.userData.kind;
    },
  };
}

// Keyboard, pointer and touch input
export class Input {
  constructor({ canvas, joystick, knob }) {
    this.canvas = canvas;
    this.joystick = joystick;
    this.knob = knob;
    this.keys = new Set();
    this.pressed = new Set();
    this.orbit = { dx: 0, dy: 0, zoom: 0 };
    this.move = { x: 0, y: 0 };
    this.touchMove = { x: 0, y: 0 };
    this.dragging = false;
    this.lastPointer = { x: 0, y: 0 };
    this.stickPointer = null;
    this.enabled = true;

    window.addEventListener('keydown', (e) => {
      if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space'].includes(e.code)) e.preventDefault();
      if (!this.keys.has(e.code)) this.pressed.add(e.code);
      this.keys.add(e.code);
    });
    window.addEventListener('keyup', (e) => {
      this.keys.delete(e.code);
      if (e.code === 'Space') this.pressed.delete('Space');
    });
    window.addEventListener('blur', () => {
      this.keys.clear();
      this.touchMove.x = 0;
      this.touchMove.y = 0;
      this.resetStick();
    });

    canvas.addEventListener('pointerdown', (e) => {
      if (e.button !== 0 && e.pointerType === 'mouse') return;
      if (e.target !== canvas) return;
      this.dragging = true;
      this.lastPointer = { x: e.clientX, y: e.clientY };
      canvas.setPointerCapture?.(e.pointerId);
      canvas.classList.add('grabbing');
    });
    canvas.addEventListener('pointermove', (e) => {
      if (!this.dragging) return;
      this.orbit.dx += (e.clientX - this.lastPointer.x) * 0.005;
      this.orbit.dy += (e.clientY - this.lastPointer.y) * 0.004;
      this.lastPointer = { x: e.clientX, y: e.clientY };
    });
    const endDrag = () => {
      this.dragging = false;
      canvas.classList.remove('grabbing');
    };
    canvas.addEventListener('pointerup', endDrag);
    canvas.addEventListener('pointercancel', endDrag);
    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();
      this.orbit.zoom += Math.sign(e.deltaY) * 0.08;
    }, { passive: false });
    canvas.addEventListener('contextmenu', (e) => e.preventDefault());

    this.bindJoystick();
  }

  bindJoystick() {
    if (!this.joystick) return;
    const update = (e) => {
      if (e.pointerId !== this.stickPointer) return;
      const rect = this.joystick.getBoundingClientRect();
      const cx = rect.left + rect.width / 2;
      const cy = rect.top + rect.height / 2;
      let dx = e.clientX - cx;
      let dy = e.clientY - cy;
      const max = rect.width * 0.34;
      const len = Math.hypot(dx, dy);
      if (len > max) { dx = (dx / len) * max; dy = (dy / len) * max; }
      this.knob.style.transform = `translate(${dx}px, ${dy}px)`;
      this.touchMove.x = dx / max;
      this.touchMove.y = -dy / max;
      this.joystick.classList.add('active');
    };
    this.joystick.addEventListener('pointerdown', (e) => {
      this.stickPointer = e.pointerId;
      this.joystick.setPointerCapture?.(e.pointerId);
      this.joystick.classList.add('active');
      update(e);
    });
    this.joystick.addEventListener('pointermove', update);
    const end = (e) => {
      if (e.pointerId !== this.stickPointer) return;
      this.resetStick();
    };
    this.joystick.addEventListener('pointerup', end);
    this.joystick.addEventListener('pointercancel', end);
    this.joystick.addEventListener('lostpointercapture', end);
  }

  resetStick() {
    this.stickPointer = null;
    this.touchMove.x = 0;
    this.touchMove.y = 0;
    if (this.knob) this.knob.style.transform = 'translate(0,0)';
    this.joystick?.classList.remove('active');
  }

  get vector() {
    let x = 0, y = 0;
    if (this.enabled) {
      if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) y += 1;
      if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) y -= 1;
      if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) x -= 1;
      if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) x += 1;
      if (this.stickPointer !== null) {
        x += this.touchMove.x;
        y += this.touchMove.y;
      }
    }
    const len = Math.hypot(x, y);
    if (len > 1) { x /= len; y /= len; }
    return { x, y };
  }

  get running() {
    return this.enabled && (this.keys.has('ShiftLeft') || this.keys.has('ShiftRight'));
  }

  wasPressed(code) {
    if (!this.enabled) return false;
    return this.pressed.has(code);
  }

  trigger(code) {
    this.pressed.add(code);
  }

  takeOrbit() {
    const o = { ...this.orbit };
    this.orbit.dx = 0;
    this.orbit.dy = 0;
    this.orbit.zoom = 0;
    return o;
  }

  endFrame() {
    this.pressed.clear();
  }
}

// Tiny procedural sound system — no audio assets required.
export class AudioSys {
  constructor() {
    this.ctx = null;
    this.enabled = true;
    this.musicOn = true;
    this.stepIndex = 0;
    this.timer = null;
    this.chords = [
      [261.63, 329.63, 392.0],
      [220.0, 261.63, 329.63],
      [174.61, 220.0, 261.63],
      [196.0, 246.94, 293.66],
    ];
    this.melody = [0, 2, 4, 2, 1, 3, 2, 0, 2, 4, 5, 4, 3, 1, 2, 0];
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.5;
    this.master.connect(this.ctx.destination);
    this.musicGain = this.ctx.createGain();
    this.musicGain.gain.value = 0.12;
    this.musicGain.connect(this.master);
    this.sfxGain = this.ctx.createGain();
    this.sfxGain.gain.value = 0.34;
    this.sfxGain.connect(this.master);
    this.startMusic();
  }

  startMusic() {
    if (!this.ctx || this.timer) return;
    this.timer = setInterval(() => this.musicStep(), 420);
  }

  stopMusic() {
    if (this.timer) clearInterval(this.timer);
    this.timer = null;
  }

  musicStep() {
    if (!this.ctx || !this.musicOn || this.ctx.state !== 'running') return;
    const bar = Math.floor(this.stepIndex / 8) % this.chords.length;
    const chord = this.chords[bar];
    const idx = this.stepIndex % 16;
    const note = chord[[0, 1, 2, 1][idx % 4]] * (idx >= 8 ? 2 : 1);
    const t = this.ctx.currentTime;
    this.tone(note * 2, 1.6, 'sine', 0.045, t, this.musicGain, 0.004);
    if (this.stepIndex % 4 === 0) {
      this.tone(chord[0] / 2, 2.6, 'triangle', 0.045, t, this.musicGain, 0.4);
      this.tone(chord[2] / 2, 2.6, 'sine', 0.03, t + 0.02, this.musicGain, 0.5);
    }
    if (this.stepIndex % 8 === 3) {
      this.tone(this.melody[idx] ? chord[this.melody[idx] % 3] * 2 : note * 2, 0.8, 'triangle', 0.035, t, this.musicGain, 0.01);
    }
    this.stepIndex++;
  }

  tone(freq, duration, type, gain, when, destination, attack = 0.01) {
    if (!this.ctx) return;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, when);
    g.gain.setValueAtTime(0.0001, when);
    g.gain.exponentialRampToValueAtTime(gain, when + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, when + duration);
    osc.connect(g);
    g.connect(destination || this.sfxGain);
    osc.start(when);
    osc.stop(when + duration + 0.05);
  }

  sweep(f0, f1, duration, type = 'sine', gain = 0.12) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(f0, t);
    osc.frequency.exponentialRampToValueAtTime(f1, t + duration);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    osc.connect(g); g.connect(this.sfxGain);
    osc.start(t); osc.stop(t + duration + 0.05);
  }

  sfx(name) {
    if (!this.ctx || !this.enabled) return;
    const t = this.ctx.currentTime;
    switch (name) {
      case 'select':
        this.tone(520, 0.08, 'triangle', 0.12, t, this.sfxGain);
        this.tone(780, 0.1, 'triangle', 0.08, t + 0.05, this.sfxGain);
        break;
      case 'confirm':
        this.tone(523, 0.1, 'triangle', 0.12, t, this.sfxGain);
        this.tone(659, 0.1, 'triangle', 0.12, t + 0.08, this.sfxGain, 0.005);
        this.tone(784, 0.2, 'triangle', 0.12, t + 0.16, this.sfxGain, 0.005);
        break;
      case 'hit':
        this.sweep(180, 60, 0.18, 'sawtooth', 0.16);
        this.tone(90, 0.12, 'square', 0.1, t, this.sfxGain);
        break;
      case 'hurt':
        this.sweep(320, 110, 0.3, 'sawtooth', 0.12);
        break;
      case 'miss':
        this.sweep(500, 240, 0.2, 'sine', 0.08);
        break;
      case 'orb':
        this.sweep(400, 900, 0.35, 'sine', 0.1);
        break;
      case 'catch':
        [523, 659, 784, 1046].forEach((f, i) => this.tone(f, 0.5, 'triangle', 0.1, t + i * 0.12, this.sfxGain));
        break;
      case 'fail':
        this.sweep(300, 120, 0.5, 'triangle', 0.1);
        break;
      case 'level':
        [392, 523, 659, 784, 1046].forEach((f, i) => this.tone(f, 0.45, 'sine', 0.09, t + i * 0.1, this.sfxGain));
        break;
      case 'heal':
        [440, 554, 659].forEach((f, i) => this.tone(f, 0.35, 'sine', 0.08, t + i * 0.08, this.sfxGain));
        break;
      case 'pickup':
        this.tone(880, 0.15, 'triangle', 0.09, t, this.sfxGain);
        this.tone(1174, 0.25, 'triangle', 0.07, t + 0.08, this.sfxGain);
        break;
      case 'encounter':
        this.sweep(200, 800, 0.45, 'triangle', 0.12);
        this.tone(220, 0.3, 'sawtooth', 0.06, t + 0.2, this.sfxGain);
        break;
      case 'step':
        this.tone(150 + Math.random() * 40, 0.04, 'triangle', 0.03, t, this.sfxGain);
        break;
    }
  }

  toggle() {
    this.enabled = !this.enabled;
    if (this.master) this.master.gain.value = this.enabled ? 0.5 : 0;
    return this.enabled;
  }
}

import * as THREE from '../vendor/three.module.js';
import {
  SPECIES, MOVES, TYPES, displayName, typeMultiplier, stageMultiplier,
  xpGain, levelUp, XP_TO_NEXT, MAX_LEVEL, statsFor,
} from './data.js';
import { buildCreature, animateCreature, material } from './models.js';

const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));

// ---------------------------------------------------------------------------
// Cinematic spirit-glade arena
// ---------------------------------------------------------------------------

function buildArena() {
  const scene = new THREE.Scene();
  scene.fog = new THREE.Fog('#c8dfd1', 26, 72);

  const sky = new THREE.Mesh(
    new THREE.SphereGeometry(180, 32, 20),
    new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      uniforms: {
        uTop: { value: new THREE.Color('#589cc4') },
        uBottom: { value: new THREE.Color('#ffe1a6') },
      },
      vertexShader: `varying vec3 vDir; void main(){ vDir = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
      fragmentShader: `
        uniform vec3 uTop; uniform vec3 uBottom; varying vec3 vDir;
        void main(){
          float h = clamp(vDir.y + 0.08, 0.0, 1.0);
          vec3 col = mix(uBottom, uTop, pow(h, 0.62));
          float glow = max(dot(normalize(vDir), normalize(vec3(-0.5,0.3,-0.7))), 0.0);
          col += vec3(1.0,0.8,0.55) * pow(glow, 12.0) * 0.5;
          gl_FragColor = vec4(col, 1.0);
        }
      `,
    }),
  );
  scene.add(sky);

  const hemi = new THREE.HemisphereLight('#dff4ff', '#4e6b46', 1.5);
  scene.add(hemi);
  const sun = new THREE.DirectionalLight('#fff0ce', 3.0);
  sun.position.set(8, 16, 9);
  sun.castShadow = true;
  sun.shadow.mapSize.set(1024, 1024);
  sun.shadow.camera.left = -12;
  sun.shadow.camera.right = 12;
  sun.shadow.camera.top = 12;
  sun.shadow.camera.bottom = -12;
  sun.shadow.bias = -0.001;
  scene.add(sun);
  const rim = new THREE.PointLight('#ffbe72', 45, 34, 2);
  rim.position.set(-9, 7, -3);
  scene.add(rim);
  const coolRim = new THREE.PointLight('#6ad7ff', 32, 30, 2);
  coolRim.position.set(9, 5, 5);
  scene.add(coolRim);

  const arena = new THREE.Group();
  scene.add(arena);

  const ground = new THREE.Mesh(
    new THREE.CylinderGeometry(16, 18.5, 1.2, 64),
    new THREE.MeshStandardMaterial({ color: '#3f7052', roughness: 1, flatShading: false }),
  );
  ground.position.y = -0.6;
  ground.receiveShadow = true;
  arena.add(ground);

  const top = new THREE.Mesh(
    new THREE.CircleGeometry(16, 64),
    new THREE.MeshStandardMaterial({ color: '#58855b', roughness: 0.95 }),
  );
  top.rotation.x = -Math.PI / 2;
  top.position.y = 0.01;
  top.receiveShadow = true;
  arena.add(top);

  const ringMat = new THREE.MeshBasicMaterial({ color: '#c8f4b0', transparent: true, opacity: 0.2, side: THREE.DoubleSide, depthWrite: false });
  for (const r of [10.5, 14.6]) {
    const ring = new THREE.Mesh(new THREE.RingGeometry(r, r + 0.09, 72), ringMat);
    ring.rotation.x = -Math.PI / 2;
    ring.position.y = 0.04;
    arena.add(ring);
  }

  const platforms = [];
  for (const [x, z] of [[-3.1, -2.6], [3.1, 2.7]]) {
    const platform = new THREE.Mesh(
      new THREE.CylinderGeometry(3.25, 3.55, 0.55, 40),
      new THREE.MeshStandardMaterial({ color: '#b4ad8d', roughness: 0.9, flatShading: false }),
    );
    platform.position.set(x, 0.28, z);
    platform.castShadow = true;
    platform.receiveShadow = true;
    arena.add(platform);

    const moss = new THREE.Mesh(
      new THREE.CircleGeometry(3.18, 40),
      new THREE.MeshStandardMaterial({ color: '#7da45f', roughness: 1 }),
    );
    moss.rotation.x = -Math.PI / 2;
    moss.position.set(x, 0.56, z);
    moss.receiveShadow = true;
    arena.add(moss);

    const rune = new THREE.Mesh(
      new THREE.RingGeometry(2.25, 2.55, 40, 1, 0, Math.PI * 1.4),
      new THREE.MeshBasicMaterial({ color: '#ecffd0', transparent: true, opacity: 0.5, side: THREE.DoubleSide, depthWrite: false }),
    );
    rune.rotation.x = -Math.PI / 2;
    rune.rotation.z = x < 0 ? 2 : -1;
    rune.position.set(x, 0.575, z);
    arena.add(rune);
    platforms.push(platform);
  }

  // Distant grove silhouettes
  const pineMat = new THREE.MeshStandardMaterial({ color: '#39634d', roughness: 1, flatShading: true });
  const trunkMat = new THREE.MeshStandardMaterial({ color: '#4a3c33', roughness: 1 });
  for (let i = 0; i < 22; i++) {
    const ang = (i / 22) * Math.PI * 2 + Math.random() * 0.2;
    const radius = 19 + Math.random() * 8;
    const tree = new THREE.Group();
    const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.3, 3.6, 6), trunkMat);
    trunk.position.y = 1.8;
    tree.add(trunk);
    for (let j = 0; j < 3; j++) {
      const cone = new THREE.Mesh(new THREE.ConeGeometry(2.0 - j * 0.5, 3.2 - j * 0.4, 7), pineMat);
      cone.position.y = 3.2 + j * 1.6;
      cone.castShadow = true;
      tree.add(cone);
    }
    tree.position.set(Math.cos(ang) * radius, -0.8 + Math.random() * 0.8, Math.sin(ang) * radius);
    tree.rotation.y = Math.random() * Math.PI;
    tree.scale.setScalar(0.8 + Math.random() * 0.8);
    arena.add(tree);
  }

  // Floating rocks
  const floaters = [];
  for (let i = 0; i < 16; i++) {
    const rock = new THREE.Mesh(
      new THREE.DodecahedronGeometry(0.4 + Math.random() * 1.3, 0),
      new THREE.MeshStandardMaterial({ color: i % 3 === 0 ? '#6c8d68' : '#7b7d6e', roughness: 1, flatShading: true }),
    );
    rock.position.set((Math.random() - 0.5) * 44, 2 + Math.random() * 12, -10 - Math.random() * 26);
    rock.rotation.set(Math.random() * 3, Math.random() * 3, Math.random() * 3);
    rock.userData.base = rock.position.clone();
    rock.userData.phase = Math.random() * 6;
    scene.add(rock);
    floaters.push(rock);
  }

  // God rays
  for (let i = 0; i < 4; i++) {
    const ray = new THREE.Mesh(
      new THREE.ConeGeometry(2.2 + i * 0.6, 24, 12, 1, true),
      new THREE.MeshBasicMaterial({ color: '#fff2c4', transparent: true, opacity: 0.035, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending }),
    );
    ray.position.set(-10 + i * 7, 10, -12 - i * 2);
    ray.rotation.z = 0.16 + i * 0.05;
    scene.add(ray);
  }

  // Petals + fireflies
  const petalCount = 110;
  const petalGeo = new THREE.BufferGeometry();
  const petalPos = new Float32Array(petalCount * 3);
  for (let i = 0; i < petalCount; i++) {
    petalPos[i * 3] = (Math.random() - 0.5) * 30;
    petalPos[i * 3 + 1] = Math.random() * 14;
    petalPos[i * 3 + 2] = (Math.random() - 0.5) * 26;
  }
  petalGeo.setAttribute('position', new THREE.BufferAttribute(petalPos, 3));
  const petals = new THREE.Points(petalGeo, new THREE.PointsMaterial({
    color: '#ffd7db', size: 0.16, transparent: true, opacity: 0.85, depthWrite: false,
  }));
  scene.add(petals);

  const flyCount = 70;
  const flyGeo = new THREE.BufferGeometry();
  const flyPos = new Float32Array(flyCount * 3);
  for (let i = 0; i < flyCount; i++) {
    flyPos[i * 3] = (Math.random() - 0.5) * 28;
    flyPos[i * 3 + 1] = 0.6 + Math.random() * 5;
    flyPos[i * 3 + 2] = (Math.random() - 0.5) * 22;
  }
  flyGeo.setAttribute('position', new THREE.BufferAttribute(flyPos, 3));
  const fireflies = new THREE.Points(flyGeo, new THREE.PointsMaterial({
    color: '#ffe98a', size: 0.12, transparent: true, opacity: 0.9, depthWrite: false,
  }));
  scene.add(fireflies);

  return { scene, petals, fireflies, floaters, platforms, topY: 0.58 };
}

// ---------------------------------------------------------------------------

export class Battle {
  constructor({ party, inventory, audio }) {
    this.party = party;
    this.inventory = inventory;
    this.audio = audio;
    this.arena = buildArena();
    this.scene = this.arena.scene;
    this.camera = new THREE.PerspectiveCamera(42, 16 / 9, 0.1, 260);
    this.camBase = new THREE.Vector3(0, 4.1, 11.2);
    this.camera.position.copy(this.camBase);
    this.camera.lookAt(0, 1.7, 0);
    this.tweens = [];
    this.busy = true;
    this.session = 0;
    this.shake = 0;
    this.time = 0;
    this.enemyGroup = null;
    this.playerGroup = null;
    this.orb = null;
    this.onEnd = null;
    this.activeIndex = 0;
    this.enemy = null;
    this.isBoss = false;
    this.cacheDom();
    this.bindUI();
  }

  cacheDom() {
    const $ = (id) => document.getElementById(id);
    this.el = {
      section: $('battle'),
      kicker: $('battle-kicker'),
      enemyCard: $('enemy-card'),
      enemyName: $('enemy-name'),
      enemyLv: $('enemy-lv'),
      enemyHp: $('enemy-hp-fill'),
      enemyHpText: $('enemy-hp-text'),
      enemyTypes: $('enemy-types'),
      enemyStatus: $('enemy-status'),
      playerCard: $('player-card'),
      playerName: $('player-name'),
      playerLv: $('player-lv'),
      playerHp: $('player-hp-fill'),
      playerHpText: $('player-hp-text'),
      playerTypes: $('player-types'),
      playerStatus: $('player-status'),
      playerExp: $('player-exp-fill'),
      playerExpText: $('player-exp-text'),
      log: $('battle-log'),
      actions: $('battle-actions'),
      party: $('battle-party'),
      floats: $('battle-floats'),
      flash: $('battle-flash'),
    };
  }

  bindUI() {
    this.el.actions.addEventListener('click', (e) => {
      const btn = e.target.closest('button');
      if (!btn || btn.disabled || this.busy) return;
      this.audio.init();
      this.audio.sfx('select');
      const cmd = btn.dataset.cmd;
      if (cmd === 'fight') this.renderMoves();
      else if (cmd === 'bag') this.renderBag();
      else if (cmd === 'party') this.renderPartySwap(false);
      else if (cmd === 'run') this.attemptRun();
      else if (cmd === 'back') this.renderMain();
      else if (btn.dataset.move != null) this.usePlayerMove(Number(btn.dataset.move));
      else if (btn.dataset.item) this.useItem(btn.dataset.item);
      else if (btn.dataset.swap != null) this.switchTo(Number(btn.dataset.swap), btn.dataset.force === '1');
    });
  }

  // ---- lifecycle ---------------------------------------------------------

  async begin(enemy, isBoss, onEnd) {
    this.session++;
    this.enemy = enemy;
    this.isBoss = isBoss;
    this.onEnd = onEnd;
    this.activeIndex = this.party.findIndex((m) => m.hp > 0);
    this.busy = true;
    this.orb = null;
    this.shake = 0;
    this.enemy.atkStage = 0;
    this.enemy.defStage = 0;

    for (const g of [this.enemyGroup, this.playerGroup]) {
      if (g) this.scene.remove(g);
    }
    this.enemyGroup = this.makeModel(enemy, -3.1, -2.6, isBoss ? 2.25 : 1.95, 0);
    this.playerGroup = this.makeModel(this.party[this.activeIndex], 3.1, 2.7, 2.05, Math.PI);
    this.scene.add(this.enemyGroup, this.playerGroup);

    this.el.section.classList.remove('hidden', 'leaving');
    this.el.kicker.textContent = isBoss ? 'GUARDIAN TRIAL · THE GROVE REMEMBERS' : 'WILD ENCOUNTER';
    this.el.kicker.classList.toggle('boss', isBoss);
    this.el.log.textContent = isBoss ? 'The ancient grove holds its breath…' : 'The grass rustles…';
    this.el.actions.innerHTML = '';
    this.renderHUD();
    this.renderPartyDots();
    this.spawnScale(this.enemyGroup, 1, 480);
    this.spawnScale(this.playerGroup, 1, 480);
    this.audio.sfx('encounter');
    await wait(500);
    if (!this.enemyGroup) return;
    this.el.log.textContent = isBoss
      ? 'The Verdant Guardian rises from the roots!'
      : `A wild ${displayName(enemy)} appeared!`;
    await wait(isBoss ? 1100 : 750);
    this.busy = false;
    this.renderMain();
  }

  makeModel(mon, x, z, scale, rotationY) {
    const g = buildCreature(mon.species);
    g.position.set(x, this.arena.topY, z);
    g.rotation.y = rotationY;
    g.userData.baseScale = scale;
    g.userData.spawn = 0.001;
    g.userData.squash = 1;
    g.userData.basePos = g.position.clone();
    g.scale.setScalar(0.001);
    return g;
  }

  spawnScale(group, target, ms) {
    const from = group.userData.spawn;
    return this.tween(ms, (p) => { group.userData.spawn = from + (target - from) * p; });
  }

  tween(ms, fn, ease = (t) => 1 - (1 - t) * (1 - t)) {
    return new Promise((resolve) => {
      this.tweens.push({ time: 0, duration: ms / 1000, fn, ease, resolve });
    });
  }

  update(dt, time) {
    this.time = time;
    // tweens
    for (let i = this.tweens.length - 1; i >= 0; i--) {
      const tw = this.tweens[i];
      tw.time += dt;
      const p = Math.min(1, tw.time / tw.duration);
      tw.fn(tw.ease(p));
      if (p >= 1) {
        this.tweens.splice(i, 1);
        tw.resolve();
      }
    }
    for (const g of [this.enemyGroup, this.playerGroup]) {
      if (!g) continue;
      animateCreature(g, time, this.busy ? 1.4 : 0);
      const s = g.userData.baseScale * Math.max(0.001, g.userData.spawn) * (g.userData.squash || 1);
      g.scale.setScalar(s);
    }
    if (this.orb) {
      this.orb.rotation.y += dt * 5;
      this.orb.rotation.z += dt * 2;
    }
    // swirling petals
    const pp = this.arena.petals.geometry.attributes.position;
    for (let i = 0; i < pp.count; i++) {
      let y = pp.getY(i) - dt * (0.35 + (i % 5) * 0.08);
      if (y < -0.5) y = 15;
      pp.setY(i, y);
      pp.setX(i, pp.getX(i) + Math.sin(time * 0.7 + i) * dt * 0.25);
    }
    pp.needsUpdate = true;
    const fp = this.arena.fireflies.geometry.attributes.position;
    for (let i = 0; i < fp.count; i++) {
      fp.setY(i, Math.max(0.4, fp.getY(i) + Math.sin(time * 1.4 + i * 1.7) * dt * 0.15));
    }
    fp.needsUpdate = true;
    this.arena.petals.material.opacity = 0.65 + Math.sin(time * 0.8) * 0.2;
    this.arena.fireflies.material.opacity = 0.6 + Math.sin(time * 1.6) * 0.3;
    this.arena.floaters.forEach((r) => {
      r.position.y = r.userData.base.y + Math.sin(time * 0.5 + r.userData.phase) * 0.7;
      r.rotation.y += dt * 0.1;
    });

    this.shake = Math.max(0, this.shake - dt * 2.6);
    const sh = this.shake;
    this.camera.position.set(
      this.camBase.x + Math.sin(time * 71) * sh * 0.55,
      this.camBase.y + Math.cos(time * 63) * sh * 0.35,
      this.camBase.z + Math.sin(time * 59) * sh * 0.2,
    );
    this.camera.lookAt(0, 1.7, 0);
  }

  resize(aspect) {
    this.camera.aspect = aspect;
    this.camera.updateProjectionMatrix();
  }

  get active() {
    return this.party[this.activeIndex];
  }

  // ---- HUD ---------------------------------------------------------------

  renderHUD() {
    const enemy = this.enemy;
    const active = this.active;
    if (!enemy || !active) return;
    const eSpecies = SPECIES[enemy.species];
    const aSpecies = SPECIES[active.species];
    this.el.enemyName.textContent = displayName(enemy);
    this.el.enemyLv.textContent = `Lv. ${enemy.level}`;
    this.el.enemyTypes.innerHTML = `<span class="type-chip t-${eSpecies.type}">${TYPES[eSpecies.type].name}</span>`;
    this.el.playerName.textContent = displayName(active);
    this.el.playerLv.textContent = `Lv. ${active.level}`;
    this.el.playerTypes.innerHTML = `<span class="type-chip t-${aSpecies.type}">${TYPES[aSpecies.type].name}</span>`;
    this.el.playerStatus.textContent = active.hp <= 0 ? 'FAINTED' : '';
    this.el.enemyStatus.textContent = enemy.hp <= 0 ? 'FAINTED' : '';
    this.setHP('enemy', enemy);
    this.setHP('player', active);
    const pct = Math.min(100, (active.exp / XP_TO_NEXT(active.level)) * 100);
    this.el.playerExp.style.width = `${pct}%`;
    this.el.playerExpText.textContent = active.level >= MAX_LEVEL ? 'MAX' : `${active.exp}/${XP_TO_NEXT(active.level)}`;
    this.renderPartyDots();
  }

  setHP(side, mon) {
    const pct = clamp((mon.hp / mon.maxHp) * 100, 0, 100);
    const fill = side === 'enemy' ? this.el.enemyHp : this.el.playerHp;
    const text = side === 'enemy' ? this.el.enemyHpText : this.el.playerHpText;
    fill.style.width = `${pct}%`;
    fill.classList.toggle('low', pct <= 50 && pct > 22);
    fill.classList.toggle('critical', pct <= 22);
    text.textContent = `${Math.max(0, mon.hp)}/${mon.maxHp}`;
  }

  renderPartyDots() {
    this.el.party.innerHTML = this.party.map((m, i) => {
      const s = SPECIES[m.species];
      const pct = clamp((m.hp / m.maxHp) * 100, 0, 100);
      return `<div class="party-dot ${i === this.activeIndex ? 'active' : ''} ${m.hp <= 0 ? 'down' : ''}" title="${displayName(m)}">
        <span class="dot-name">${displayName(m)}</span>
        <span class="dot-hp"><i style="width:${pct}%;background:${TYPES[s.type].color}"></i></span>
      </div>`;
    }).join('');
  }

  log(text) {
    this.el.log.innerHTML = text;
  }

  float(text, side, cls = '') {
    const div = document.createElement('div');
    div.className = `battle-float ${side} ${cls}`;
    div.textContent = text;
    this.el.floats.appendChild(div);
    setTimeout(() => div.remove(), 1300);
  }

  flashScreen(color = '#fff7df') {
    this.el.flash.style.background = color;
    this.el.flash.classList.remove('go');
    void this.el.flash.offsetWidth;
    this.el.flash.classList.add('go');
  }

  // ---- command menus -----------------------------------------------------

  renderMain() {
    if (this.busy) return;
    this.el.actions.innerHTML = `
      <button class="battle-btn cmd-fight" data-cmd="fight"><b>FIGHT</b><span>Choose a move</span></button>
      <button class="battle-btn cmd-bag" data-cmd="bag"><b>BAG</b><span>${this.inventory.orbs} orbs · ${this.inventory.potions} tonics</span></button>
      <button class="battle-btn cmd-party" data-cmd="party"><b>SWAP</b><span>${this.party.filter((m) => m.hp > 0).length} ready</span></button>
      <button class="battle-btn cmd-run" data-cmd="run"><b>RUN</b><span>${this.isBoss ? 'No escape' : 'Try to flee'}</span></button>
    `;
  }

  renderMoves() {
    if (this.busy) return;
    const active = this.active;
    const buttons = active.moves.map((entry, i) => {
      const move = MOVES[entry.id];
      return `<button class="move-btn t-${move.type}" data-move="${i}" ${entry.pp <= 0 ? 'disabled' : ''}>
        <span class="move-name">${move.name}</span>
        <span class="move-type">${TYPES[move.type].name}</span>
        <span class="move-pp">${entry.pp}/${entry.maxPp} PP</span>
      </button>`;
    }).join('');
    this.el.actions.innerHTML = `<div class="move-grid">${buttons}</div>
      <button class="battle-btn small back-btn" data-cmd="back"><b>BACK</b></button>`;
  }

  renderBag() {
    if (this.busy) return;
    const orbLabel = this.isBoss ? 'Sealed here' : `${this.inventory.orbs} left`;
    this.el.actions.innerHTML = `
      <button class="battle-btn item-btn" data-item="orb" ${this.inventory.orbs <= 0 || this.isBoss ? 'disabled' : ''}>
        <b>Star Orb</b><span>${orbLabel}</span>
      </button>
      <button class="battle-btn item-btn" data-item="potion" ${this.inventory.potions <= 0 ? 'disabled' : ''}>
        <b>Grove Tonic</b><span>${this.inventory.potions} left</span>
      </button>
      <button class="battle-btn small back-btn" data-cmd="back"><b>BACK</b></button>`;
  }

  renderPartySwap(force) {
    if (this.busy && !force) return;
    const rows = this.party.map((m, i) => {
      const s = SPECIES[m.species];
      const pct = clamp((m.hp / m.maxHp) * 100, 0, 100);
      const disabled = m.hp <= 0 || (i === this.activeIndex && !force);
      return `<button class="swap-row ${i === this.activeIndex ? 'current' : ''}" data-swap="${i}" data-force="${force ? 1 : 0}" ${disabled ? 'disabled' : ''}>
        <span class="swap-dot" style="background:${TYPES[s.type].color}"></span>
        <span class="swap-name">${displayName(m)}<small>Lv. ${m.level} · ${TYPES[s.type].name}</small></span>
        <span class="swap-hp"><i style="width:${pct}%"></i><em>${Math.max(0, m.hp)}/${m.maxHp}</em></span>
      </button>`;
    }).join('');
    this.el.actions.innerHTML = `<div class="swap-list">${rows}</div>
      ${force ? '' : '<button class="battle-btn small back-btn" data-cmd="back"><b>BACK</b></button>'}`;
  }

  // ---- actions -----------------------------------------------------------

  async usePlayerMove(index) {
    if (this.busy) return;
    const active = this.active;
    const entry = active.moves[index];
    if (!entry) return;
    this.busy = true;
    this.el.actions.innerHTML = '';
    if (entry.pp <= 0) {
      this.log(`${displayName(active)} has no power left for that move!`);
      this.busy = false;
      this.renderMain();
      return;
    }
    entry.pp--;
    const move = MOVES[entry.id];
    this.log(`${displayName(active)} used <b>${move.name}</b>!`);
    await this.performMove(active, this.enemy, move, true);
    if (!this.enemy) return;
    if (this.enemy.hp <= 0) {
      await this.enemyFainted();
      return;
    }
    await wait(250);
    await this.enemyTurn();
  }

  async performMove(attacker, defender, move, byPlayer) {
    const attackerGroup = byPlayer ? this.playerGroup : this.enemyGroup;
    const defenderGroup = byPlayer ? this.enemyGroup : this.playerGroup;
    if (!attackerGroup || !defenderGroup) return;
    await this.lunge(attackerGroup, defenderGroup, byPlayer);
    const hit = Math.random() <= move.accuracy;
    if (!hit) {
      this.log(`But ${displayName(defender)} dodged it!`);
      this.audio.sfx('miss');
      await wait(650);
      return;
    }
    if (move.power > 0) {
      const { dmg, eff, crit } = this.damage(attacker, defender, move);
      defender.hp = Math.max(0, defender.hp - dmg);
      this.audio.sfx('hit');
      this.shake = 0.5;
      defenderGroup.userData.squash = 0.82;
      setTimeout(() => { if (defenderGroup) defenderGroup.userData.squash = 1; }, 160);
      this.float(`-${dmg}`, byPlayer ? 'enemy' : 'player', crit ? 'crit' : '');
      this.setHP(byPlayer ? 'enemy' : 'player', defender);
      this.renderPartyDots();
      const fx = byPlayer ? this.el.enemyCard : this.el.playerCard;
      fx.classList.remove('shake');
      void fx.offsetWidth;
      fx.classList.add('shake');
      await wait(420);
      if (crit) this.log('A critical hit!');
      if (eff > 1) this.log("It's super effective!");
      else if (eff < 1) this.log("It's not very effective…");
      await wait(650);
    } else {
      await this.statusMove(attacker, defender, move, byPlayer);
    }
  }

  async statusMove(attacker, defender, move, byPlayer) {
    const defenderGroup = byPlayer ? this.enemyGroup : this.playerGroup;
    if (move.effect === 'atkDown') {
      defender.atkStage = Math.max(-3, defender.atkStage - 1);
      this.log(`${displayName(defender)}'s Attack fell!`);
    } else if (move.effect === 'defUp') {
      attacker.defStage = Math.min(3, attacker.defStage + 1);
      this.log(`${displayName(attacker)}'s Defense rose!`);
    } else if (move.effect === 'drain') {
      const heal = Math.round(attacker.maxHp * 0.22);
      attacker.hp = Math.min(attacker.maxHp, attacker.hp + heal);
      this.audio.sfx('heal');
      this.log(`${displayName(attacker)} drained ${heal} vitality!`);
      this.float(`+${heal}`, byPlayer ? 'player' : 'enemy', 'heal');
      this.setHP(byPlayer ? 'player' : 'enemy', attacker);
    }
    if (defenderGroup) {
      defenderGroup.userData.squash = 0.92;
      setTimeout(() => { if (defenderGroup) defenderGroup.userData.squash = 1; }, 160);
    }
    this.renderHUD();
    await wait(850);
  }

  async lunge(attackerGroup, defenderGroup, byPlayer) {
    const base = attackerGroup.userData.basePos;
    const dir = byPlayer ? -1 : 1;
    const dx = byPlayer ? -0.55 : 0.55;
    const dz = byPlayer ? -0.4 : 0.4;
    await this.tween(180, (p) => {
      attackerGroup.position.x = base.x + dx * p;
      attackerGroup.position.z = base.z + dz * p;
      attackerGroup.rotation.z = dir * 0.06 * p;
    });
    await this.tween(180, (p) => {
      attackerGroup.position.x = base.x + dx * (1 - p);
      attackerGroup.position.z = base.z + dz * (1 - p);
      attackerGroup.rotation.z = dir * 0.06 * (1 - p);
    });
  }

  damage(attacker, defender, move) {
    const atk = attacker.atk * stageMultiplier(attacker.atkStage);
    const def = defender.def * stageMultiplier(defender.defStage);
    const eff = typeMultiplier(move.type, SPECIES[defender.species].type);
    const stab = move.type === SPECIES[attacker.species].type ? 1.2 : 1;
    const crit = Math.random() < 0.07;
    let dmg = ((2 * attacker.level / 5 + 2) * move.power * atk / def) / 50 + 2;
    dmg = dmg * eff * stab * (crit ? 1.5 : 1) * (0.86 + Math.random() * 0.28);
    return { dmg: Math.max(1, Math.round(dmg)), eff, crit };
  }

  chooseEnemyMove() {
    const enemy = this.enemy;
    const available = enemy.moves.filter((m) => m.pp > 0);
    if (!available.length) return MOVES.tackle;
    const scored = available.map((entry) => {
      const move = MOVES[entry.id];
      let score = move.power * typeMultiplier(move.type, SPECIES[this.active.species].type);
      if (move.effect) score = 30;
      return { move, entry, score: score * (0.75 + Math.random() * 0.5) };
    });
    scored.sort((a, b) => b.score - a.score);
    const pick = scored[Math.random() < 0.72 ? 0 : Math.floor(Math.random() * scored.length)];
    pick.entry.pp = Math.max(0, pick.entry.pp - 1);
    return pick.move;
  }

  async enemyTurn() {
    if (!this.enemy || this.enemy.hp <= 0 || !this.active || this.active.hp <= 0) {
      this.busy = false;
      this.renderMain();
      return;
    }
    const move = this.chooseEnemyMove();
    await wait(150);
    this.log(`Wild ${displayName(this.enemy)} used <b>${move.name}</b>!`);
    await this.performMove(this.enemy, this.active, move, false);
    if (!this.active) return;
    this.renderHUD();
    if (this.active.hp <= 0) {
      await this.playerFainted();
    } else {
      this.busy = false;
      this.renderMain();
    }
  }

  async enemyFainted() {
    this.busy = true;
    this.enemy.hp = 0;
    this.setHP('enemy', this.enemy);
    this.el.enemyStatus.textContent = 'FAINTED';
    this.log(`${displayName(this.enemy)} fainted!`);
    this.audio.sfx('fail');
    this.el.actions.innerHTML = '';
    await this.spawnScale(this.enemyGroup, 0, 380);
    await wait(450);
    const gained = xpGain(this.enemy, this.isBoss);
    await this.awardXp(gained);
    await wait(350);
    await this.finish(this.isBoss ? 'boss' : 'win');
  }

  async awardXp(amount) {
    const mon = this.active;
    if (!mon) return;
    mon.exp += amount;
    this.log(`${displayName(mon)} gained <b>${amount} XP</b>!`);
    this.audio.sfx('level');
    this.renderHUD();
    await wait(900);
    while (mon.exp >= XP_TO_NEXT(mon.level) && mon.level < MAX_LEVEL) {
      mon.exp -= XP_TO_NEXT(mon.level);
      const result = levelUp(mon);
      this.log(`<b>${displayName(mon)} grew to Lv. ${mon.level}!</b>`);
      this.audio.sfx('level');
      this.float(`LV. ${mon.level}`, 'player', 'level');
      this.renderHUD();
      await wait(950);
      if (result?.learned?.length) {
        const names = result.learned.map((id) => MOVES[id].name).join(', ');
        this.log(`${displayName(mon)} learned <b>${names}</b>!`);
        await wait(1100);
      }
    }
    this.renderHUD();
  }

  async playerFainted() {
    this.busy = true;
    this.log(`${displayName(this.active)} fainted!`);
    this.audio.sfx('fail');
    this.el.actions.innerHTML = '';
    await this.spawnScale(this.playerGroup, 0, 380);
    await wait(500);
    const next = this.party.findIndex((m) => m.hp > 0);
    if (next === -1) {
      this.log('All of your partners are exhausted…');
      await wait(1100);
      await this.finish('lost');
      return;
    }
    this.log('Choose your next partner.');
    this.busy = false;
    this.el.actions.innerHTML = '';
    this.renderPartySwap(true);
  }

  // ---- catching / items / switching / running ---------------------------

  async useItem(item) {
    if (this.busy) return;
    if (item === 'orb') {
      if (this.isBoss) return;
      if (this.inventory.orbs <= 0) return;
      await this.attemptCatch();
    } else if (item === 'potion') {
      if (this.inventory.potions <= 0) return;
      if (this.active.hp >= this.active.maxHp) {
        this.log(`${displayName(this.active)} is already full of beans.`);
        return;
      }
      this.busy = true;
      this.el.actions.innerHTML = '';
      this.inventory.potions--;
      const healed = Math.min(this.active.maxHp, this.active.hp + 28 + this.active.level * 2);
      const amount = healed - this.active.hp;
      this.active.hp = healed;
      this.audio.sfx('heal');
      this.log(`${displayName(this.active)} drank a Grove Tonic and recovered ${amount} HP!`);
      this.float(`+${amount}`, 'player', 'heal');
      this.renderHUD();
      await wait(800);
      await this.enemyTurn();
    }
  }

  async attemptCatch() {
    this.busy = true;
    this.el.actions.innerHTML = '';
    this.inventory.orbs--;
    this.log('You tossed a Star Orb!');
    this.audio.sfx('orb');

    const orb = new THREE.Mesh(
      new THREE.SphereGeometry(0.3, 14, 10),
      new THREE.MeshStandardMaterial({ color: '#f6e4b0', emissive: '#ffbe4d', emissiveIntensity: 0.9, roughness: 0.3, metalness: 0.4, flatShading: true }),
    );
    const band = new THREE.Mesh(new THREE.TorusGeometry(0.3, 0.05, 6, 18), material('#e06a54', { emissive: '#c84b3a', emissiveIntensity: 0.4 }));
    band.rotation.x = Math.PI / 2;
    orb.add(band);
    orb.position.copy(this.playerGroup.position).add(new THREE.Vector3(-0.2, 2.3, 0));
    this.scene.add(orb);
    this.orb = orb;

    const start = orb.position.clone();
    const end = this.enemyGroup.position.clone().add(new THREE.Vector3(0, 1.3, 0));
    await this.tween(620, (p) => {
      orb.position.lerpVectors(start, end, p);
      orb.position.y += Math.sin(p * Math.PI) * 2.4;
      orb.rotation.x = p * Math.PI * 6;
    }, (t) => t);
    this.flashScreen('#fff3c9');
    this.audio.sfx('hit');
    await this.spawnScale(this.enemyGroup, 0, 260);
    await wait(220);

    this.log('The orb wobbles…');
    let shakes = 0;
    const chance = this.catchChance();
    const success = Math.random() < chance;
    const totalShakes = success ? 3 : Math.random() < 0.5 ? 1 : 2;
    for (let i = 0; i < totalShakes; i++) {
      shakes++;
      await this.tween(280, (p) => {
        orb.rotation.z = Math.sin(p * Math.PI * 2) * 0.5;
        orb.position.y = end.y - 0.3 + Math.abs(Math.sin(p * Math.PI)) * 0.22;
      });
      this.audio.sfx('orb');
      await wait(320);
    }

    if (success) {
      this.audio.sfx('catch');
      this.flashScreen('#fff2b0');
      this.log(`<b>Gotcha!</b> ${displayName(this.enemy)} was caught!`);
      const star = new THREE.Mesh(new THREE.OctahedronGeometry(0.55, 0), new THREE.MeshBasicMaterial({ color: '#ffe27a', transparent: true, opacity: 0.85 }));
      star.position.copy(end);
      this.scene.add(star);
      for (let i = 0; i < 3; i++) {
        await this.tween(260, (p) => {
          star.scale.setScalar(0.3 + p * 1.7);
          star.material.opacity = 0.9 * (1 - p);
          star.rotation.y += 0.2;
        });
      }
      this.scene.remove(star);
      await wait(700);
      this.scene.remove(orb);
      this.orb = null;
      await this.finish('caught');
    } else {
      this.audio.sfx('fail');
      this.scene.remove(orb);
      this.orb = null;
      this.log(`Oh no! ${displayName(this.enemy)} broke free!`);
      await this.spawnScale(this.enemyGroup, 1, 300);
      await wait(850);
      await this.enemyTurn();
    }
  }

  catchChance() {
    const hpRatio = this.enemy.hp / this.enemy.maxHp;
    const species = SPECIES[this.enemy.species];
    const base = 0.48 + (1 - hpRatio) * 0.42;
    const levelPenalty = this.enemy.level * 0.011;
    const rarity = species.catch / 0.6;
    return clamp((base - levelPenalty) * rarity + 0.04, 0.08, 0.94);
  }

  async switchTo(index, force) {
    if (index === this.activeIndex && !force) return;
    const next = this.party[index];
    if (!next || next.hp <= 0) return;
    this.busy = true;
    this.el.actions.innerHTML = '';
    if (this.playerGroup) {
      await this.spawnScale(this.playerGroup, 0, 260);
      this.scene.remove(this.playerGroup);
    }
    this.activeIndex = index;
    next.atkStage = 0;
    next.defStage = 0;
    this.playerGroup = this.makeModel(next, 3.1, 2.7, 2.05, Math.PI);
    this.scene.add(this.playerGroup);
    this.spawnScale(this.playerGroup, 1, 380);
    this.audio.sfx('confirm');
    this.log(`Go, <b>${displayName(next)}</b>!`);
    this.renderHUD();
    await wait(700);
    if (force) {
      this.busy = false;
      this.renderMain();
      return;
    }
    await this.enemyTurn();
  }

  async attemptRun() {
    if (this.busy) return;
    if (this.isBoss) {
      this.log('There is no running from the grove guardian!');
      return;
    }
    this.busy = true;
    this.el.actions.innerHTML = '';
    const chance = clamp(0.55 + (this.active.spd - this.enemy.spd) * 0.025, 0.25, 0.95);
    if (Math.random() < chance) {
      this.log('You slipped away through the tall grass.');
      await wait(800);
      await this.finish('run');
    } else {
      this.log("You couldn't get away!");
      await wait(700);
      await this.enemyTurn();
    }
  }

  async finish(result) {
    this.busy = true;
    this.session++;
    const callback = this.onEnd;
    const enemy = this.enemy;
    this.onEnd = null;
    this.el.actions.innerHTML = '';
    await wait(650);
    this.el.section.classList.add('leaving');
    await wait(420);
    this.el.section.classList.add('hidden');
    this.el.section.classList.remove('leaving');
    for (const g of [this.enemyGroup, this.playerGroup]) {
      if (g) this.scene.remove(g);
    }
    if (this.orb) this.scene.remove(this.orb);
    this.enemyGroup = null;
    this.playerGroup = null;
    this.orb = null;
    this.enemy = null;
    this.busy = true;
    callback?.(result, enemy);
  }
}

