const thumbs = {};

function makeThumbnails() {
  const tr = new THREE.WebGLRenderer({ antialias: true, alpha: true, preserveDrawingBuffer: true });
  tr.setPixelRatio(1);
  tr.setSize(300, 300, false);
  tr.toneMapping = THREE.ACESFilmicToneMapping;
