  g.add(body);
  add(body, geo.sphere, '#464a8c', [0, 0.72, -0.04], [0.34, 0.33, 0.55]);
  add(body, geo.sphere, '#a9b9ee', [0, 0.62, 0.17], [0.22, 0.2, 0.36]);
  add(body, geo.sphere, '#343764', [0, 0.88, -0.22], [0.28, 0.24, 0.36]);

  const head = new THREE.Group();
  head.position.set(0, 1.05, 0.42);
  body.add(head);
  add(head, geo.sphere, '#4b4f94', [0, 0, 0], [0.3, 0.29, 0.28]);
  add(head, geo.sphere, '#d9e4ff', [0, -0.08, 0.22], [0.16, 0.11, 0.12]);
  add(head, geo.sphereLow, '#252546', [0, -0.02, 0.32], [0.045, 0.035, 0.025]);
  for (const side of [-1, 1]) {
    add(head, geo.sphereLow, '#c9f4ff', [side * 0.12, 0.06, 0.23], [0.05, 0.065, 0.03], [0, 0, 0], { emissive: '#79d9ff', emissiveIntensity: 1.4 });
    const ear = add(head, geo.cone, '#464a8c', [side * 0.2, 0.28, -0.02], [0.1, 0.34, 0.07], [0, 0, side * 0.3]);
    ear.castShadow = true;
    add(head, geo.cone, '#b7c6f2', [side * 0.2, 0.28, 0.005], [0.05, 0.21, 0.04], [0, 0, side * 0.3]);
  }
  // crescent horns
  for (const side of [-1, 1]) {
    const horn = new THREE.Mesh(
      new THREE.TorusGeometry(0.14, 0.035, 6, 12, Math.PI * 1.35),
      new THREE.MeshStandardMaterial({ color: '#dff8ff', emissive: '#8fe4ff', emissiveIntensity: 1.5, roughness: 0.35, flatShading: true }),
    );
    horn.position.set(side * 0.16, 0.34, 0.02);
    horn.rotation.set(Math.PI / 2, side * 0.7, side * 0.4);
    head.add(horn);
  }
  // constellation markings
  const glow = [];
  for (let i = 0; i < 5; i++) {
    const star = add(body, geo.sphereLow, '#e8ffff', [Math.sin(i * 1.9) * 0.22, 0.72 + Math.cos(i * 2.4) * 0.14, -0.28 + i * 0.1], [0.024, 0.024, 0.024], [0, 0, 0], { emissive: '#a6f2ff', emissiveIntensity: 2.2 });
    star.castShadow = false;
    glow.push(star);
  }
  for (const side of [-1, 1]) {
    for (const z of [-0.3, 0.28]) {
      add(body, geo.cyl, '#3b3e72', [side * 0.22, 0.35, z], [0.07, 0.68, 0.07]);
      add(body, geo.sphere, '#252848', [side * 0.22, 0.06, z + 0.04], [0.1, 0.06, 0.13]);
    }
  }
  const tail = new THREE.Group();
  tail.position.set(0, 0.84, -0.52);
  body.add(tail);
  add(tail, geo.sphere, '#464a8c', [0, 0.02, -0.22], [0.12, 0.12, 0.34]);
  add(tail, geo.sphere, '#5b60a8', [-0.03, 0.18, -0.42], [0.1, 0.1, 0.26], [0.4, 0, 0.2]);
  const tip = add(tail, geo.octa, '#d9f9ff', [-0.02, 0.3, -0.56], [0.11, 0.11, 0.18], [0, 0, 0], { emissive: '#9beeff', emissiveIntensity: 1.8 });
  glow.push(tip);
  const halo = new THREE.Mesh(
    new THREE.TorusGeometry(0.38, 0.02, 4, 24),
    new THREE.MeshBasicMaterial({ color: '#bcefff', transparent: true, opacity: 0.55, depthWrite: false }),
