  halo.rotation.x = Math.PI / 2;
  halo.position.set(0, 1.55, 0.3);
  g.add(halo);

  g.userData.anim = { body, head, ears: [], tail: [tail], glow, halo, bodyY: 0.02 };
  return g;
}

function buildSolaris() {
  const g = new THREE.Group();
  const body = new THREE.Group();
  g.add(body);
  add(body, geo.sphere, '#f2c85b', [0, 0.9, 0], [0.38, 0.42, 0.36]);
  add(body, geo.sphere, '#fff0bd', [0, 0.8, 0.2], [0.26, 0.3, 0.18]);
  add(body, geo.sphere, '#ffe48a', [0, 1.16, -0.06], [0.3, 0.2, 0.28]);

  const head = new THREE.Group();
  head.position.set(0, 1.34, 0.12);
  body.add(head);
  add(head, geo.sphere, '#f7d269', [0, 0, 0], [0.28, 0.27, 0.27]);
  add(head, geo.sphere, '#fff4cf', [0, -0.03, 0.2], [0.14, 0.11, 0.1]);
  const beak = add(head, geo.cone, '#ed8a36', [0, -0.04, 0.32], [0.075, 0.2, 0.075], [Math.PI / 2, 0, 0]);
  beak.castShadow = false;
  eyePair(head, 0.04, 0.23, 0.11, 0.065);
  // crest feathers
  for (let i = 0; i < 3; i++) {
    add(head, geo.cone, i === 1 ? '#fff1ae' : '#f5c94f', [(i - 1) * 0.09, 0.3 + (i === 1 ? 0.08 : 0), -0.02], [0.055, 0.34, 0.04], [0.15, 0, (i - 1) * 0.35], { emissive: '#ffd45e', emissiveIntensity: 0.5 });
  }

  const wings = [];
  for (const side of [-1, 1]) {
    const pivot = new THREE.Group();
    pivot.position.set(side * 0.25, 1.0, -0.05);
    body.add(pivot);
    const wing = wingShape('#f8d96f');
    wing.scale.set(side * 1.25, 1.15, 1);
    wing.rotation.z = side * 0.06;
    const inner = wingShape('#ffeaa0');
    inner.scale.set(side * 0.8, 0.75, 1);
    inner.position.z = 0.01;
    pivot.add(wing, inner);
    wings.push(pivot);
  }

  const tail = [];
  for (let i = 0; i < 3; i++) {
    const feather = add(body, geo.cone, i === 1 ? '#fff0a8' : '#f2b943', [(i - 1) * 0.12, 0.7, -0.42], [0.07, 0.6, 0.045], [1.1 + i * 0.1, 0, (i - 1) * 0.35], { emissive: '#ffcd54', emissiveIntensity: 0.45 });
    tail.push(feather);
  }

  for (const side of [-1, 1]) {
    add(body, geo.cyl, '#d99a2f', [side * 0.14, 0.3, 0.06], [0.028, 0.55, 0.028]);
    add(body, geo.sphere, '#e9ae3d', [side * 0.14, 0.03, 0.11], [0.08, 0.035, 0.12]);
  }

  const halo = new THREE.Mesh(
    new THREE.TorusGeometry(0.4, 0.028, 5, 28),
    new THREE.MeshStandardMaterial({ color: '#fff6c8', emissive: '#ffd75e', emissiveIntensity: 2.0, roughness: 0.3, flatShading: true }),
  );
  halo.rotation.x = Math.PI / 2;
  halo.position.set(0, 1.72, 0.1);
  g.add(halo);

  const glow = [];
  for (const side of [-1, 1]) {
    const wisp = add(body, geo.octa, '#fff2b0', [side * 0.6, 1.3, -0.1], [0.06, 0.06, 0.06], [0, 0, 0], { emissive: '#ffe67a', emissiveIntensity: 2.2 });
    wisp.castShadow = false;
    glow.push(wisp);
  }

  g.userData.anim = { body, head, tail, wings, halo, glow, bodyY: 0.04 };
  return g;
}

