    ring.scale.setScalar(1 + Math.sin(time * 1.8) * 0.08);
  }
  if (anim.freckles) {
    anim.freckles.forEach((s, i) => {
      s.material.opacity = 0.5 + Math.sin(time * 2.4 + i * 1.7) * 0.4;
    });
  }
