235: function spawnWild(spawn, isTitle = false) {
236:   const mon = createCreature(spawn.species, spawn.level);
237:   const root = new THREE.Group();
238:   const model = buildCreature(spawn.species);
239:   model.scale.setScalar(spawn.species === 'elderwood' ? 1.5 : 0.9);
240:   root.add(model);
241:   const shadow = shadowBlob(spawn.species === 'elderwood' ? 1.8 : 1.1);
242:   root.add(shadow);
243:   const typeColor = TYPES[SPECIES[spawn.species].type].color;
244:   const ring = new THREE.Mesh(
245:     new THREE.RingGeometry(0.75, 0.95, 28),
246:     new THREE.MeshBasicMaterial({ color: typeColor, transparent: true, opacity: 0.4, side: THREE.DoubleSide, depthWrite: false }),
247:   );
248:   ring.rotation.x = -Math.PI / 2;
249:   ring.position.y = 0.03;
250:   root.add(ring);
251:   const x = spawn.x, z = spawn.z;
252:   root.position.set(x, world.heightAt(x, z) + 0.01, z);
253:   scene.add(root);
254: 
255:   const wild = {
256:     mon,
257:     spawn,
258:     root,
259:     model,
260:     shadow,
261:     ring,
262:     home: new THREE.Vector2(x, z),
263:     target: new THREE.Vector2(x, z),
264:     timer: 2 + Math.random() * 5,
265:     phase: Math.random() * 8,
266:     scaleBase: spawn.species === 'elderwood' ? 1.5 : 0.9,
267:     isTitle,
268:     active: true,
269:   };
270:   if (isTitle) {
271:     model.scale.setScalar(wild.scaleBase * 0.001);
272:     wild.spawnScale = 0;
273:   }
274:   if (!isTitle) state.wilds.push(wild);
275:   return wild;
276: }
