278: function pickWanderTarget(wild) {
279:   for (let i = 0; i < 8; i++) {
280:     const a = Math.random() * Math.PI * 2;
281:     const r = 1.5 + Math.random() * 6;
282:     const x = wild.home.x + Math.cos(a) * r;
283:     const z = wild.home.y + Math.sin(a) * r;
284:     if (world.heightAt(x, z) > 0.5) {
285:       wild.target.set(x, z);
286:       return;
287:     }
288:   }
289:   wild.target.copy(wild.home);
290: }
