292: function despawnWild(wild, respawnMs) {
293:   wild.active = false;
294:   scene.remove(wild.root);
295:   state.wilds = state.wilds.filter((w) => w !== wild);
296:   if (state.near === wild) state.near = null;
297:   if (respawnMs) {
298:     setTimeout(() => {
299:       if (state.bossDefeated && state.caught.length >= 3) return;
300:       const level = Math.min(12, wild.spawn.level + Math.floor(Math.random() * 2));
301:       const w = spawnWild({ ...wild.spawn, level });
302:       w.spawnScale = 0;
303:       w.model.scale.setScalar(0.001);
304:     }, respawnMs);
305:   }
306: }
