602: function startBattle(wild, isBoss = false) {
603:   if (state.mode !== 'world' || state.cooldown > 0) return;
604:   if (state.party.every((m) => m.hp <= 0)) {
605:     toast('Your team needs to rest at the campfire first.', 'warn');
606:     return;
607:   }
608:   state.mode = 'battle';
609:   state.activeWild = wild;
610:   input.enabled = false;
611:   hidePrompt();
612:   closeModal();
613:   document.body.classList.add('in-battle');
614:   flashScreen('#fff6d9');
615:   audio.sfx('encounter');
616:   const mon = wild.mon;
617:   if (!state.seen.includes(mon.species)) state.seen.push(mon.species);
618: 
619:   battle.begin(mon, isBoss, (result) => endBattle(result, wild, isBoss));
620: }
621: 
622: function endBattle(result, wild, isBoss) {
623:   state.mode = 'world';
624:   state.cooldown = 1.6;
625:   input.enabled = true;
626:   document.body.classList.remove('in-battle');
627:   flashScreen('#ffeec2');
628: 
629:   const enemy = wild?.mon;
630:   if (result === 'caught' && enemy) {
631:     state.catchCount++;
632:     state.battlesWon++;
633:     const isNew = !state.caught.includes(enemy.species);
634:     if (isNew) {
635:       state.caught.push(enemy.species);
636:       audio.sfx('catch');
637:       toast(`New field note: <b>${SPECIES[enemy.species].name}</b>!`, 'success', 4200);
638:     }
639:     const joined = { ...enemy, hp: Math.max(1, enemy.hp), exp: enemy.exp || 0 };
640:     if (state.party.length < 6) {
641:       state.party.push(joined);
642:       toast(`${displayName(joined)} joined your team.`, 'success', 3000);
643:     } else {
644:       state.ranch++;
645:       toast(`${displayName(joined)} is resting at the Isles Ranch.`, 'info', 3200);
646:     }
647:     if (wild) despawnWild(wild, 65000);
648:     renderPartyHUD();
649:     updateQuest();
650:     if (questPhase() === 2 && state.caught.length === 3) {
651:       setTimeout(() => toast('A green light rises from the <b>northern shrine</b>…', 'warn', 5200), 900);
652:     }
653:   } else if (result === 'win' && enemy) {
654:     state.battlesWon++;
655:     state.inventory.orbs += Math.random() < 0.35 ? 1 : 0;
656:     if (wild) despawnWild(wild, 32000);
657:     toast(`${SPECIES[enemy.species].name} was defeated.`, 'info', 2400);
658:   } else if (result === 'boss') {
659:     state.battlesWon++;
660:     state.bossDefeated = true;
661:     state.inventory.orbs += 3;
662:     state.inventory.potions += 2;
663:     removeBoss();
664:     updateQuest();
665:     saveGame();
666:     showEnding();
667:   } else if (result === 'lost') {
668:     for (const m of state.party) healCreature(m);
669:     player.pos.set(world.campPos.x, 0, world.campPos.z - 2);
670:     player.pos.y = world.heightAt(player.pos.x, player.pos.z);
671:     trainer.position.copy(player.pos);
