677:     const away = new THREE.Vector2(wild.root.position.x - player.pos.x, wild.root.position.z - player.pos.z).normalize();
678:     if (away.lengthSq() === 0) away.set(1, 0);
679:     wild.home.set(wild.root.position.x + away.x * 6, wild.root.position.z + away.y * 6);
680:     wild.target.copy(wild.home);
