682:   }
683: 
684:   if (result !== 'lost') {
685:     const lead = state.party[0];
686:     if (lead) {
687:       // Bank EXP overflow safely and keep HUD fresh
688:       if (lead.exp >= XP_TO_NEXT(lead.level)) lead.exp = Math.min(lead.exp, XP_TO_NEXT(lead.level) - 1);
