778: function canWalk(x, z) {
779:   if (Math.hypot(x, z) > 88) return false;
780:   for (let i = 0; i < world.colliders.length; i++) {
781:     const c = world.colliders[i];
782:     const rr = c.r + 0.42;
783:     const dx = x - c.x, dz = z - c.z;
784:     if (dx * dx + dz * dz < rr * rr) return false;
785:   }
786:   return true;
787: }
788: 
789: function updatePlayer(dt) {
790:   const v = input.vector;
791:   const moving = Math.hypot(v.x, v.y) > 0.05;
792:   const speed = input.running ? 8.4 : 5.0;
793:   const f = { x: -Math.sin(cameraYaw), z: -Math.cos(cameraYaw) };
794:   const r = { x: Math.cos(cameraYaw), z: -Math.sin(cameraYaw) };
795:   const tx = (f.x * v.y + r.x * v.x) * speed;
796:   const tz = (f.z * v.y + r.z * v.x) * speed;
797:   player.vel.x = damp(player.vel.x, tx, 12, dt);
798:   player.vel.z = damp(player.vel.z, tz, 12, dt);
799: 
800:   if (Math.hypot(player.vel.x, player.vel.z) > 0.12) {
801:     const nx = player.pos.x + player.vel.x * dt;
802:     const nz = player.pos.z + player.vel.z * dt;
803:     if (canWalk(nx, player.pos.z)) player.pos.x = nx;
804:     else player.vel.x *= 0.2;
805:     if (canWalk(player.pos.x, nz)) player.pos.z = nz;
806:     else player.vel.z *= 0.2;
807:   }
808: 
809:   // jump
810:   if (input.wasPressed('Space') && player.grounded && state.mode === 'world') {
811:     player.jumpVel = 6.4;
812:     player.grounded = false;
813:   }
814:   if (!player.grounded) {
815:     player.jumpVel -= 19 * dt;
816:     player.jump += player.jumpVel * dt;
817:     if (player.jump <= 0) {
818:       player.jump = 0;
819:       player.jumpVel = 0;
820:       player.grounded = true;
821:     }
822:   }
823: 
824:   player.pos.y = world.heightAt(player.pos.x, player.pos.z) + player.jump;
825:   trainer.position.copy(player.pos);
826:   const sp = Math.hypot(player.vel.x, player.vel.z);
827:   if (sp > 0.25) {
828:     const targetFacing = Math.atan2(player.vel.x, player.vel.z);
829:     player.facing = angleLerp(player.facing, targetFacing, 1 - Math.exp(-14 * dt));
830:   }
831:   trainer.rotation.y = player.facing;
832:   player.walk = damp(player.walk, Math.min(1, sp / 5), 10, dt);
833:   animateTrainer(trainer, performance.now() / 1000, player.walk, !player.grounded);
834: 
835:   // footsteps
836:   player.stepTimer -= dt;
837:   if (sp > 2 && player.grounded && player.stepTimer <= 0) {
838:     player.stepTimer = input.running ? 0.26 : 0.4;
839:     audio.sfx('step');
840:   }
841: }
