847: function updateWilds(dt, time) {
848:   let nearest = null;
849:   let nearestDist = 4.1;
850:   for (const w of state.wilds) {
851:     if (!w.active) continue;
852:     animateCreature(w.model, time + w.phase, 0);
853:     const p = w.root.position;
854:     w.timer -= dt;
855:     if (w.timer <= 0) {
856:       pickWanderTarget(w);
857:       w.timer = 2.5 + Math.random() * 6;
858:     }
859:     const dx = w.target.x - p.x;
860:     const dz = w.target.y - p.z;
861:     const dist = Math.hypot(dx, dz);
862:     if (dist > 0.2) {
863:       const speed = 0.8;
864:       const nx = p.x + (dx / dist) * speed * dt;
865:       const nz = p.z + (dz / dist) * speed * dt;
866:       if (world.heightAt(nx, nz) > 0.35) {
867:         p.x = nx;
868:         p.z = nz;
869:         p.y = world.heightAt(nx, nz) + 0.01;
870:         w.model.rotation.y = angleLerp(w.model.rotation.y, Math.atan2(dx, dz), 1 - Math.exp(-5 * dt));
871:       } else {
872:         w.timer = 0;
873:       }
874:     }
875:     // avoid standing inside the player
876:     const pd = Math.hypot(p.x - player.pos.x, p.z - player.pos.z);
877:     if (pd < 1.2) {
878:       const a = Math.atan2(p.x - player.pos.x, p.z - player.pos.z);
879:       p.x += Math.sin(a) * dt * 1.4;
880:       p.z += Math.cos(a) * dt * 1.4;
881:     }
882:     if (state.mode === 'world' || state.mode === 'title') {
883:       w.ring.material.opacity = 0.28 + Math.sin(time * 2 + w.phase) * 0.08;
884:     }
885:     if (state.mode === 'world') {
886:       if (pd < nearestDist) { nearestDist = pd; nearest = w; }
887:       if (w.spawnScale !== undefined && w.spawnScale < 1) {
888:         w.spawnScale = Math.min(1, w.spawnScale + dt * 2.4);
889:         w.model.scale.setScalar(w.scaleBase * w.spawnScale);
890:       }
891:     }
892:   }
893:   if (state.mode === 'world' && state.cooldown <= 0) {
894:     if (nearest) {
895:       if (state.near !== nearest) {
896:         state.near = nearest;
897:         setPrompt(`Battle ${displayName(nearest.mon)} · Lv. ${nearest.mon.level}`);
898:       }
899:       nearest.ring.material.opacity = 0.55 + Math.sin(time * 4) * 0.2;
900:       nearest.ring.scale.setScalar(1.1 + Math.sin(time * 4) * 0.06);
901:     } else {
902:       state.near = null;
903:       if (!nearBoss() && player.pos.distanceTo(world.campPos) >= 4.2 && Math.hypot(player.pos.x - world.hutPos.x, player.pos.z - world.hutPos.z) >= 6) {
904:         hidePrompt();
905:       }
906:     }
907:   }
908: 
909:   if (state.boss) {
910:     animateCreature(state.boss.model, time * 0.8, 2);
911:     state.boss.ring.rotation.z = time * 0.35;
912:     state.boss.halo.rotation.z = -time * 0.22;
913:     state.boss.halo.scale.setScalar(1 + Math.sin(time * 1.6) * 0.04);
914:     state.boss.ring.material.opacity = 0.4 + Math.sin(time * 2.2) * 0.16;
915:   }
916: }
917: 
918: function updateProximityPrompt() {
919:   if (state.mode !== 'world' || state.cooldown > 0) return;
920:   if (nearBoss()) {
921:     setPrompt('Challenge the Verdant Guardian');
922:     return;
923:   }
924:   const { wild } = nearestWild();
925:   if (wild) {
926:     setPrompt(`Battle ${displayName(wild.mon)} · Lv. ${wild.mon.level}`);
927:     return;
928:   }
929:   if (player.pos.distanceTo(world.campPos) < 4.2) {
930:     setPrompt('Rest by the campfire');
931:     return;
932:   }
933:   if (Math.hypot(player.pos.x - world.hutPos.x, player.pos.z - world.hutPos.z) < 6) {
934:     setPrompt('Open your field journal');
