963: function updateWorldCamera(dt, time) {
964:   const orbit = input.takeOrbit();
965:   if (orbit.dx) cameraYaw -= orbit.dx;
966:   if (orbit.dy) cameraPitch = clamp(cameraPitch + orbit.dy, 0.08, 1.12);
967:   if (orbit.zoom) cameraDist = clamp(cameraDist + orbit.zoom * 10, 6.5, 18);
968: 
969:   const px = player.pos.x;
970:   const pz = player.pos.z;
971:   const py = player.pos.y;
972:   const cp = Math.cos(cameraPitch);
973:   let desired = new THREE.Vector3(
974:     px + Math.sin(cameraYaw) * cameraDist * cp,
975:     py + 2.2 + Math.sin(cameraPitch) * cameraDist,
976:     pz + Math.cos(cameraYaw) * cameraDist * cp,
977:   );
978:   const ground = world.heightAt(desired.x, desired.z) + 1.7;
979:   if (desired.y < ground) desired.y = ground;
980:   camera.position.lerp(desired, 1 - Math.exp(-7 * dt));
981:   const lookTarget = new THREE.Vector3(px, py + 1.35, pz);
982:   cameraLook.lerp(lookTarget, 1 - Math.exp(-10 * dt));
983:   camera.lookAt(cameraLook);
984: }
