1140: // ---------------------------------------------------------------------------
1141: // Main loop
1142: // ---------------------------------------------------------------------------
1143: 
1144: const clock = new THREE.Clock();
1145: let elapsed = 0;
1146: 
1147: function tick() {
1148:   requestAnimationFrame(tick);
1149:   const dt = Math.min(0.05, clock.getDelta());
1150:   elapsed += dt;
1151:   const time = elapsed;
1152: 
1153:   world.update(dt, time);
1154:   updateWilds(dt, time);
1155:   if (state.boss) {
1156:     const bd = Math.hypot(state.boss.x - player.pos.x, state.boss.z - player.pos.z);
1157:     if (state.mode === 'world' && bd < 9) setPrompt('Challenge the Verdant Guardian');
1158:   }
1159: 
1160:   if (state.mode === 'world' || state.mode === 'menu') {
1161:     if (state.mode === 'world' && !state.modalOpen) updatePlayer(dt);
1162:     else animateTrainer(trainer, time, 0, false);
1163:     updateWorldCamera(dt, time);
1164:     checkPickups();
1165:     updateProximityPrompt();
1166:     updateZone();
1167:     if (state.cooldown > 0) state.cooldown = Math.max(0, state.cooldown - dt);
1168:   } else if (state.mode === 'title' || state.mode === 'starter') {
1169:     animateTrainer(trainer, time, 0, false);
1170:     updateTitleCamera(dt, time);
1171:     updateProximityPrompt();
1172:   }
1173: 
1174:   if (state.mode === 'battle' || document.body.classList.contains('in-battle')) {
1175:     battle.update(dt, time);
1176:     updateBattleCamera();
