244: export function createCreature(speciesId, level, opts = {}) {
245:   const species = SPECIES[speciesId];
246:   const stats = statsFor(speciesId, level);
247:   const learned = species.moves.filter(([lvl]) => lvl <= level);
248:   while (learned.length < 2) learned.push(species.moves[learned.length]);
249:   const moves = learned.slice(-4).map(([, id]) => ({
250:     id,
251:     pp: MOVES[id].pp,
252:     maxPp: MOVES[id].pp,
253:   }));
254:   const shiny = opts.shiny ?? Math.random() < 1 / shinyOdds(speciesId);
255:   const shinySeed = shiny ? newShinySeed() : null;
256:   return {
257:     uid: nextUid++,
258:     species: speciesId,
259:     level,
