async attemptCatch() {
  this.busy = true;
  this.el.actions.innerHTML = '';
  this.inventory.orbs--;
  this.log('You tossed a Star Orb!');
  this.audio.sfx('orb');

  const orb = new THREE.Mesh(
    new THREE.SphereGeometry(0.3, 14, 10),
    new THREE.MeshStandardMaterial({ color: '#f6e4b0', emissive: '#ffbe4d', emissiveIntensity: 0.9, roughness: 0.3, metalness: 0.4, flatShading: true }),
  );
  const band = new THREE.Mesh(new THREE.TorusGeometry(0.3, 0.05, 6, 18), material('#e06a54', { emissive: '#c84b3a', emissiveIntensity: 0.4 }));
  band.rotation.x = Math.PI / 2;
  orb.add(band);
  orb.position.copy(this.playerGroup.position).add(new THREE.Vector3(-0.2, 2.3, 0));
  this.scene.add(orb);
  this.orb = orb;

  const start = orb.position.clone();
  const end = this.enemyGroup.position.clone().add(new THREE.Vector3(0, 1.3, 0));
  await this.tween(620, (p) => {
    orb.position.lerpVectors(start, end, p);
    orb.position.y += Math.sin(p * Math.PI) * 2.4;
    orb.rotation.x = p * Math.PI * 6;
  }, (t) => t);
  this.flashScreen('#fff3c9');
  this.audio.sfx('hit');
  await this.spawnScale(this.enemyGroup, 0, 260);
  await wait(220);

  this.log('The orb wobbles…');
  let shakes = 0;
  const chance = this.catchChance();
  const success = Math.random() < chance;
  const totalShakes = success ? 3 : Math.random() < 0.5 ? 1 : 2;
  for (let i = 0; i < totalShakes; i++) {
    shakes++;
    await this.tween(280, (p) => {
      orb.rotation.z = Math.sin(p * Math.PI * 2) * 0.5;
      orb.position.y = end.y - 0.3 + Math.abs(Math.sin(p * Math.PI)) * 0.22;
    });
    this.audio.sfx('orb');
    await wait(320);
  }

  if (success) {
    this.audio.sfx('catch');
    this.flashScreen('#fff2b0');
    this.log(`<b>Gotcha!</b> ${displayName(this.enemy)} was caught!`);
    const star = new THREE.Mesh(new THREE.OctahedronGeometry(0.55, 0), new THREE.MeshBasicMaterial({ color: '#ffe27a', transparent: true, opacity: 0.85 }));
    star.position.copy(end);
    this.scene.add(star);
    for (let i = 0; i < 3; i++) {
      await this.tween(260, (p) => {
        star.scale.setScalar(0.3 + p * 1.7);
        star.material.opacity = 0.9 * (1 - p);
        star.rotation.y += 0.2;
      });
    }
    this.scene.remove(star);
    await wait(700);
    this.scene.remove(orb);
    this.orb = null;
    await this.finish('caught');
  } else {
    this.audio.sfx('fail');
    this.scene.remove(orb);
    this.orb = null;
    this.log(`Oh no! ${displayName(this.enemy)} broke free!`);
    await this.spawnScale(this.enemyGroup, 1, 300);
    await wait(850);
    await this.enemyTurn();
  }
}

catchChance() {
  const hpRatio = this.enemy.hp / this.enemy.maxHp;
  const species = SPECIES[this.enemy.species];
  const base = 0.48 + (1 - hpRatio) * 0.42;
  const levelPenalty = this.enemy.level * 0.011;
  const rarity = species.catch / 0.6;
  return clamp((base - levelPenalty) * rarity + 0.04, 0.08, 0.94);
}

