@media (max-height: 520px) and (orientation: landscape) {
  .hud-left { max-width: 44vw; }
  .quest-copy p { display: none; }
  .party-list { max-width: 44vw; }
  .zone-hud { top: auto; bottom: calc(var(--safe-bottom) + 12px); left: 50%; right: auto; transform: translateX(-50%); flex-direction: row; }
  .joystick { width: 106px; height: 106px; left: calc(var(--safe-left) + 18px); bottom: calc(var(--safe-bottom) + 16px); }
  .touch-actions { bottom: calc(var(--safe-bottom) + 18px); }
  .action-btn { width: 68px; height: 68px; font-size: 23px; }
  .jump-btn { width: 52px; height: 52px; font-size: 18px; }
  .prompt { bottom: calc(var(--safe-bottom) + 128px); font-size: 11px; }
  .battle-card { width: min(34vw, 235px); }
  .enemy-card { top: calc(var(--safe-top) + 52px); }
  .player-card { bottom: 34%; }
  .battle-bottom { left: calc(var(--safe-left) + 50px); right: calc(var(--safe-right) + 50px); }
  .battle-log { min-height: 32px; font-size: 10px; padding: 5px 10px; }
  .battle-actions { grid-template-columns: repeat(4, 1fr); }
  .battle-btn { min-height: 42px; }
  .move-btn { min-height: 42px; }
  .toasts { top: calc(var(--safe-top) + 58px); }
  .title-content { margin-bottom: 0; }
  .logo span { font-size: clamp(48px, 9vw, 76px); }
  .logo span:last-child { font-size: clamp(42px, 8vw, 64px); }
  .tagline { margin: 8px 0 12px; }
  .logo-mark { width: 44px; height: 44px; margin-bottom: 0; }
  .logo-star { font-size: 30px; }
  .title-actions { flex-direction: row; width: auto; flex-wrap: wrap; justify-content: center; }
  .big-btn { width: 220px; }
  .starter-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); max-width: 920px; }
  .starter-art { width: 82px; height: 82px; }
  .starter-card h3 { font-size: 19px; }
  .starter-card p { min-height: 28px; font-size: 9.5px; }
  .starter-head h2 { font-size: 24px; }
  .starter-head p { display: none; }
}

@media (max-width: 420px) {
  .title-content { margin-bottom: 0; }
  .logo span { font-size: 66px; }
  .logo span:last-child { font-size: 57px; }
  .tagline { font-size: 9.5px; }
  .title-actions { width: min(300px, 92vw); }
  .hud-left { max-width: calc(100vw - 112px); }
  .quest-copy p { display: none; }
  .party-list { gap: 4px; }
  .party-chip { min-width: 68px; padding: 3px 5px; }
  .resource { padding: 3px 7px 3px 5px; font-size: 10px; }
  .resource-row { gap: 4px; }
  .toasts { top: calc(var(--safe-top) + 176px); }
  .battle-card { width: 48vw; }
  .battle-card-head > span:first-child { font-size: 13px; }
  .battle-bottom { left: 6px; right: 6px; }
  .battle-log { font-size: 10px; padding: 7px 10px; }
  .battle-actions { gap: 4px; }
  .battle-btn { min-height: 44px; }
  .battle-btn b { font-size: 9.5px; }
  .battle-btn span { display: none; }
  .move-name { font-size: 10.5px; }
}

/* reduce motion for accessibility */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

