.payment-note p { margin: 0; font-size: 9px; line-height: 1.5; color: #6f7f6d; }
.payment-note code { background: #fffaf0; padding: 1px 4px; border-radius: 4px; }

.redeem-row { display: flex; gap: 8px; flex-wrap: wrap; }
