  min-width: 200px;
  padding: 11px 13px;
  border-radius: 12px;
  border: 1.5px solid #cbb98f;
  background: #fffdf5;
  color: #3c4f44;
  font: 800 12px var(--font);
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.redeem-row input:focus { outline: 2px solid #e2b64c; outline-offset: 1px; }
.redeem-row .primary-btn { font-size: 10px; padding: 10px 18px; box-shadow: 0 3px 0 #9b7226; }

/* ---- Online trade ------------------------------------------------------- */

.trade-panel { display: flex; flex-direction: column; gap: 12px; }
.trade-statusbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 12px;
  border-radius: 12px;
  background: #f0e5cc;
  border: 1px solid #d6c49d;
  font-size: 10px;
  font-weight: 800;
  color: #5d6d62;
}
.trade-dot { width: 9px; height: 9px; border-radius: 50%; background: #a7a396; box-shadow: 0 0 0 3px rgba(167, 163, 150, 0.22); }
.trade-dot.ok { background: #5bb46b; box-shadow: 0 0 0 3px rgba(91, 180, 107, 0.24); }
.trade-dot.wait { background: #e0ab3c; box-shadow: 0 0 0 3px rgba(224, 171, 60, 0.24); animation: shinyPulse 1.4s ease-in-out infinite; }
.trade-dot.bad { background: #d0604a; box-shadow: 0 0 0 3px rgba(208, 96, 74, 0.22); }
.trade-leave { margin-left: auto; font-size: 9px; padding: 6px 11px; background: #fffaf0; border: 1px solid #c7b58f; border-radius: 10px; color: #5e6c61; font-weight: 800; }

.trade-lobby-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 10px; }
.trade-lobby-card {
  padding: 14px;
  border-radius: 14px;
  background: #fffaf0;
  border: 1.5px solid #dfd0ae;
}
.trade-lobby-card b { display: block; font-family: var(--font-display); font-size: 15px; color: #3b5144; margin-bottom: 3px; }
.trade-lobby-card p { margin: 0 0 9px; font-size: 9.5px; line-height: 1.45; color: #788575; }
.trade-lobby-card .primary-btn { font-size: 10px; padding: 9px 16px; box-shadow: 0 3px 0 #9b7226; }
.trade-join-row { display: flex; gap: 7px; }
.trade-join-row input {
  flex: 1;
  min-width: 0;
  padding: 9px 11px;
  border-radius: 10px;
  border: 1.5px solid #cbb98f;
  background: #fffdf5;
  font: 900 12px var(--font);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #3c4f44;
}
.trade-note { margin: 9px 0 0; font-size: 8.5px; line-height: 1.5; color: #8c9788; text-align: center; }
.trade-room-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; flex-wrap: wrap; }
.trade-room-code {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 10px;
  border-radius: 10px;
  background: #eef5e7;
  border: 1px solid #bfd4b2;
  font-size: 9.5px;
  color: #5e7464;
}
.trade-room-code b { font: 900 15px var(--font); letter-spacing: 0.18em; color: #335b45; }
.trade-copy { font-size: 8px; padding: 4px 8px; border-radius: 8px; background: #fffaf0; border: 1px solid #c7b58f; color: #5e6c61; font-weight: 800; }
.trade-remote-name { font-size: 9px; font-weight: 800; color: #84907f; }
.trade-columns { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.trade-column {
  min-width: 0;
  padding: 10px;
  border-radius: 14px;
  background: #fffaf0;
  border: 1.5px solid #dfd0ae;
}
.trade-column h4 { margin: 0 0 7px; font-size: 13px; color: #3b5144; }
.trade-mon-list { display: flex; flex-direction: column; gap: 5px; max-height: 250px; overflow-y: auto; touch-action: pan-y; padding-right: 2px; }
.trade-mon {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 5px 7px;
  border-radius: 10px;
