}
.trade-mon:hover { border-color: #c9ae6f; }
.trade-mon.selected { border-color: #b58c2c; box-shadow: 0 0 0 2px rgba(242, 195, 79, 0.35); }
.trade-mon:disabled { opacity: 0.45; }
.trade-thumb { width: 36px; height: 36px; flex: 0 0 36px; display: grid; place-items: center; border-radius: 9px; background: radial-gradient(circle at 50% 40%, #edf5df, #dbe7cc); }
.trade-thumb img { width: 100%; height: 100%; object-fit: contain; }
.trade-mon-copy { display: flex; flex-direction: column; min-width: 0; flex: 1; }
.trade-mon-copy b { font-size: 10px; color: #3c5145; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.trade-mon-copy small { font-size: 8px; color: #8a9584; text-transform: capitalize; }
