.trade-subhead { margin: 7px 0 1px; font-size: 8px; font-weight: 900; letter-spacing: 0.14em; text-transform: uppercase; color: #9a8a68; }
.trade-offer-slot { min-height: 78px; display: grid; place-items: center; border-radius: 11px; border: 1.5px dashed #d8c8a4; background: #fffdf5; padding: 8px; }
.trade-empty { margin: 0; font-size: 9px; color: #9aa494; text-align: center; }
.trade-offer-mon { display: flex; align-items: center; gap: 8px; width: 100%; }
.trade-offer-mon b { display: block; font-size: 11px; color: #3c5145; }
.trade-offer-mon small { font-size: 8px; color: #8a9584; text-transform: capitalize; }
.trade-locked { margin-left: auto; font: 900 7px var(--font); letter-spacing: 0.1em; color: #3f7b4c; background: #dff0dc; border: 1px solid #a9cfa9; border-radius: 999px; padding: 2px 5px; }
.trade-actions { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.trade-actions .primary-btn { font-size: 10px; padding: 9px 16px; box-shadow: 0 3px 0 #9b7226; }
.trade-actions .ghost-btn { font-size: 10px; padding: 9px 14px; background: #f1e5cb; border: 1px solid #bfae88; border-radius: 12px; color: #4a5b4d; font-weight: 800; }
.trade-log { margin: 0; min-height: 22px; display: flex; flex-direction: column; gap: 2px; font-size: 9px; line-height: 1.45; color: #7d8a79; }
.trade-log b { color: #46604f; }

@media (max-width: 720px) {
  .shop-grid { grid-template-columns: 1fr; }
  .shop-card { padding: 10px; }
  .shop-glyph { flex-basis: 41px; width: 41px; height: 41px; font-size: 18px; }
  .trade-columns { grid-template-columns: 1fr; }
  .trade-mon-list { max-height: 190px; }
  .journal-clock { margin-left: 0; }
  .journal-nav { gap: 6px; }
  .shop-wallet b { font-size: 16px; }
  .owned-list { grid-template-columns: 1fr; }
  .ranch-grid { grid-template-columns: 1fr 1fr; }
  .icon-row { gap: 5px; }
  .icon-btn { width: 38px; height: 38px; font-size: 15px; }
  .resource { font-size: 10px; padding: 3px 7px 3px 5px; }
  .resource-row { gap: 4px; flex-wrap: wrap; justify-content: flex-end; max-width: 60vw; }
