/* Toasts */
.toasts {
  position: absolute;
  top: calc(var(--safe-top) + 78px);
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: center;
  width: min(480px, calc(100vw - 24px));
  pointer-events: none;
  z-index: 6;
}
.toast {
  padding: 10px 17px;
  border-radius: 13px;
  background: rgba(23, 45, 41, 0.94);
  border: 1.5px solid rgba(255, 240, 200, 0.32);
  color: #fff6dd;
  font-size: 12.5px;
  line-height: 1.35;
  text-align: center;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
  opacity: 0;
  transform: translateY(-8px) scale(0.97);
  transition: opacity 0.28s, transform 0.28s;
  backdrop-filter: blur(8px);
}
.toast.show { opacity: 1; transform: translateY(0) scale(1); }
.toast.out { opacity: 0; transform: translateY(-6px) scale(0.98); }
.toast b { color: #ffdc82; }
.toast kbd { background: rgba(255, 255, 255, 0.14); vertical-align: middle; }
.toast-success { background: rgba(34, 79, 51, 0.95); border-color: rgba(164, 236, 168, 0.45); }
.toast-warn { background: rgba(97, 66, 20, 0.95); border-color: rgba(255, 206, 105, 0.55); }

