.screen {
  position: fixed;
  inset: 0;
  z-index: 20;
  pointer-events: auto;
  overflow: hidden;
}

.title-screen {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  padding: calc(var(--safe-top) + 18px) calc(var(--safe-right) + 20px) calc(var(--safe-bottom) + 26px) calc(var(--safe-left) + 20px);
}
