636:   fill.intensity = 0.16 + sky.day * 0.42 + sky.night * 0.28;
637:   hemi.intensity = 0.3 + sky.day * 1.25;
638:   hemi.color.set(sky.day > 0.2 ? '#dff4ff' : '#93a8e8');
639:   hemi.groundColor.set(sky.day > 0.2 ? '#6b8251' : '#2c3546');
640:   scene.fog.color.copy(sky.fog);
641:   renderer.toneMappingExposure = 0.72 + sky.day * 0.36;
642:   campGlow.intensity = 1.5 + sky.night * 13;
643:   updateTimeChip();
