688: function saveGame() {
689:   if (!state.party.length) return;
690:   const data = {
691:     party: state.party,
692:     inventory: state.inventory,
693:     ranchMons: state.ranchMons,
694:     caught: state.caught,
695:     seen: state.seen,
696:     catchCount: state.catchCount,
697:     battlesWon: state.battlesWon,
698:     bossDefeated: state.bossDefeated,
699:     startedAt: state.startedAt,
700:     ranch: state.ranch,
701:     gameTime: state.gameTime,
702:     gameDay: state.gameDay,
703:     selectedFlute: state.selectedFlute,
704:     shinyFound: state.shinyFound,
705:     pos: { x: player.pos.x, z: player.pos.z },
706:     savedAt: Date.now(),
707:   };
708:   try {
709:     localStorage.setItem(SAVE_KEY, JSON.stringify(data));
710:   } catch { /* storage may be unavailable */ }
711: }
