713: function readSave() {
714:   try {
715:     const raw = localStorage.getItem(SAVE_KEY);
716:     if (!raw) return null;
717:     const data = JSON.parse(raw);
718:     if (!Array.isArray(data.party) || !data.party.length) return null;
719:     if (!data.party.every((m) => SPECIES[m.species])) return null;
720:     return data;
721:   } catch {
722:     return null;
723:   }
724: }
