726: function normalizeMon(mon) {
727:   if (!mon || !SPECIES[mon.species]) return null;
728:   mon.level = clamp(Math.round(Number(mon.level) || 1), 1, MAX_LEVEL);
729:   if (mon.shiny === undefined) mon.shiny = !!mon.appearance?.shiny;
730:   if (mon.shiny && !mon.shinySeed) mon.shinySeed = makeShinySeed();
731:   if (!mon.shiny) mon.shinySeed = null;
732:   mon.appearance = mon.shiny && mon.shinySeed ? { shiny: true, seed: mon.shinySeed } : null;
733:   if (!Number.isFinite(mon.hp)) mon.hp = mon.maxHp;
734:   mon.hp = clamp(mon.hp, 0, mon.maxHp);
735:   return mon;
736: }
737: 
738: function applySave(data) {
739:   state.party = (data.party || []).map(normalizeMon).filter(Boolean);
740:   battle.party = state.party;
741:   const inv = defaultInventory();
742:   Object.assign(inv, data.inventory || {});
743:   if (!Array.isArray(inv.flutes) || !inv.flutes.length) inv.flutes = ['willow'];
744:   inv.flutes = FLUTE_ORDER.filter((id) => inv.flutes.includes(id));
745:   if (!inv.flutes.length) inv.flutes = ['willow'];
746:   inv.owned = Array.isArray(inv.owned) ? inv.owned : [];
747:   inv.skins = Array.isArray(inv.skins) ? inv.skins : [];
748:   inv.badges = Array.isArray(inv.badges) ? inv.badges : [];
749:   inv.potions = Math.max(0, Number(inv.potions) || 0);
750:   inv.resonance = clamp(Number(inv.resonance) || 0, 0, 0.3);
751:   inv.lumen = Math.max(0, Number(inv.lumen) || 0);
752:   // Old saves used Star Orbs; convert their value into the new currency.
753:   if (data.inventory?.orbs) inv.lumen += data.inventory.orbs * 20;
754:   if (data.inventory?.orbs && !data.inventory?.flutes) inv.flutes = ['willow', 'silver', 'amber'];
755:   state.inventory = inv;
756:   battle.inventory = state.inventory;
757:   state.ranchMons = (data.ranchMons || []).map(normalizeMon).filter(Boolean);
758:   state.caught = data.caught || [];
759:   state.seen = data.seen || [];
760:   state.catchCount = data.catchCount || 0;
761:   state.battlesWon = data.battlesWon || 0;
762:   state.bossDefeated = !!data.bossDefeated;
763:   state.startedAt = data.startedAt || Date.now();
764:   state.ranch = data.ranch || state.ranchMons.length;
765:   state.gameTime = Number.isFinite(data.gameTime) ? data.gameTime : 0.34;
766:   state.gameDay = Math.max(1, Number(data.gameDay) || 1);
767:   state.selectedFlute = data.selectedFlute || 'willow';
768:   state.shinyFound = data.shinyFound || 0;
769:   player.pos.set(data.pos?.x || 0, 0, data.pos?.z || 0);
770:   player.pos.y = world.heightAt(player.pos.x, player.pos.z);
771:   trainer.position.copy(player.pos);
772:   cameraLook.set(player.pos.x, player.pos.y + 1.4, player.pos.z);
773:   cameraYaw = 0;
774:   cameraPitch = 0.3;
775:   cameraDist = 11.5;
776:   syncFluteUnlocks(false);
777:   applySky();
778:   refreshTrainerCosmetics();
779: }
