317:   makeModel(mon, x, z, scale, rotationY) {
318:     const g = buildCreature(mon);
319:     g.position.set(x, this.arena.topY, z);
320:     g.rotation.y = rotationY;
321:     g.userData.baseScale = scale;
322:     g.userData.spawn = 0.001;
323:     g.userData.squash = 1;
324:     g.userData.basePos = g.position.clone();
325:     g.scale.setScalar(0.001);
326:     return g;
327:   }
328: 
329:   spawnScale(group, target, ms) {
330:     const from = group.userData.spawn;
331:     return this.tween(ms, (p) => { group.userData.spawn = from + (target - from) * p; });
332:   }
333: 
334:   tween(ms, fn, ease = (t) => 1 - (1 - t) * (1 - t)) {
335:     return new Promise((resolve) => {
336:       this.tweens.push({ time: 0, duration: ms / 1000, fn, ease, resolve });
337:     });
338:   }
339: 
340:   update(dt, time) {
341:     this.time = time;
342:     // tweens
343:     for (let i = this.tweens.length - 1; i >= 0; i--) {
344:       const tw = this.tweens[i];
345:       tw.time += dt;
346:       const p = Math.min(1, tw.time / tw.duration);
347:       tw.fn(tw.ease(p));
348:       if (p >= 1) {
349:         this.tweens.splice(i, 1);
350:         tw.resolve();
351:       }
352:     }
353:     for (const g of [this.enemyGroup, this.playerGroup]) {
354:       if (!g) continue;
355:       animateCreature(g, time, this.busy ? 1.4 : 0);
356:       const s = g.userData.baseScale * Math.max(0.001, g.userData.spawn) * (g.userData.squash || 1);
357:       g.scale.setScalar(s);
358:     }
359:     // swirling petals
360:     const pp = this.arena.petals.geometry.attributes.position;
361:     for (let i = 0; i < pp.count; i++) {
362:       let y = pp.getY(i) - dt * (0.35 + (i % 5) * 0.08);
363:       if (y < -0.5) y = 15;
364:       pp.setY(i, y);
365:       pp.setX(i, pp.getX(i) + Math.sin(time * 0.7 + i) * dt * 0.25);
366:     }
367:     pp.needsUpdate = true;
368:     const fp = this.arena.fireflies.geometry.attributes.position;
369:     for (let i = 0; i < fp.count; i++) {
370:       fp.setY(i, Math.max(0.4, fp.getY(i) + Math.sin(time * 1.4 + i * 1.7) * dt * 0.15));
371:     }
372:     fp.needsUpdate = true;
373:     this.arena.petals.material.opacity = 0.65 + Math.sin(time * 0.8) * 0.2;
374:     this.arena.fireflies.material.opacity = 0.6 + Math.sin(time * 1.6) * 0.3;
375:     this.arena.floaters.forEach((r) => {
376:       r.position.y = r.userData.base.y + Math.sin(time * 0.5 + r.userData.phase) * 0.7;
377:       r.rotation.y += dt * 0.1;
378:     });
379: 
380:     this.shake = Math.max(0, this.shake - dt * 2.6);
381:     const sh = this.shake;
382:     this.camera.position.set(
383:       this.camBase.x + Math.sin(time * 71) * sh * 0.55,
384:       this.camBase.y + Math.cos(time * 63) * sh * 0.35,
385:       this.camBase.z + Math.sin(time * 59) * sh * 0.2,
386:     );
387:     this.camera.lookAt(0, 1.7, 0);
388:   }
