570:   async performMove(attacker, defender, move, byPlayer) {
571:     const attackerGroup = byPlayer ? this.playerGroup : this.enemyGroup;
572:     const defenderGroup = byPlayer ? this.enemyGroup : this.playerGroup;
573:     if (!attackerGroup || !defenderGroup) return;
574:     await this.lunge(attackerGroup, defenderGroup, byPlayer);
575:     const hit = Math.random() <= move.accuracy;
576:     if (!hit) {
577:       this.log(`But ${displayName(defender)} dodged it!`);
578:       this.audio.sfx('miss');
579:       await wait(650);
580:       return;
581:     }
582:     if (move.power > 0) {
583:       const { dmg, eff, crit } = this.damage(attacker, defender, move);
584:       defender.hp = Math.max(0, defender.hp - dmg);
585:       this.audio.sfx('hit');
586:       this.shake = 0.5;
587:       defenderGroup.userData.squash = 0.82;
588:       setTimeout(() => { if (defenderGroup) defenderGroup.userData.squash = 1; }, 160);
589:       this.float(`-${dmg}`, byPlayer ? 'enemy' : 'player', crit ? 'crit' : '');
590:       this.setHP(byPlayer ? 'enemy' : 'player', defender);
591:       this.renderPartyDots();
592:       const fx = byPlayer ? this.el.enemyCard : this.el.playerCard;
593:       fx.classList.remove('shake');
594:       void fx.offsetWidth;
595:       fx.classList.add('shake');
596:       await wait(420);
597:       if (crit) this.log('A critical hit!');
598:       if (eff > 1) this.log("It's super effective!");
599:       else if (eff < 1) this.log("It's not very effective…");
600:       await wait(650);
601:     } else {
602:       await this.statusMove(attacker, defender, move, byPlayer);
603:     }
604:   }
605: 
606:   async statusMove(attacker, defender, move, byPlayer) {
607:     const defenderGroup = byPlayer ? this.enemyGroup : this.playerGroup;
608:     if (move.effect === 'atkDown') {
609:       defender.atkStage = Math.max(-3, defender.atkStage - 1);
610:       this.log(`${displayName(defender)}'s Attack fell!`);
611:     } else if (move.effect === 'defUp') {
612:       attacker.defStage = Math.min(3, attacker.defStage + 1);
613:       this.log(`${displayName(attacker)}'s Defense rose!`);
614:     } else if (move.effect === 'drain') {
615:       const heal = Math.round(attacker.maxHp * 0.22);
616:       attacker.hp = Math.min(attacker.maxHp, attacker.hp + heal);
617:       this.audio.sfx('heal');
618:       this.log(`${displayName(attacker)} drained ${heal} vitality!`);
619:       this.float(`+${heal}`, byPlayer ? 'player' : 'enemy', 'heal');
620:       this.setHP(byPlayer ? 'player' : 'enemy', attacker);
621:     }
622:     if (defenderGroup) {
623:       defenderGroup.userData.squash = 0.92;
624:       setTimeout(() => { if (defenderGroup) defenderGroup.userData.squash = 1; }, 160);
625:     }
626:     this.renderHUD();
627:     await wait(850);
628:   }
629: 
630:   async lunge(attackerGroup, defenderGroup, byPlayer) {
631:     const base = attackerGroup.userData.basePos;
632:     const dir = byPlayer ? -1 : 1;
633:     const dx = byPlayer ? -0.55 : 0.55;
634:     const dz = byPlayer ? -0.4 : 0.4;
635:     await this.tween(180, (p) => {
636:       attackerGroup.position.x = base.x + dx * p;
637:       attackerGroup.position.z = base.z + dz * p;
638:       attackerGroup.rotation.z = dir * 0.06 * p;
639:     });
640:     await this.tween(180, (p) => {
641:       attackerGroup.position.x = base.x + dx * (1 - p);
642:       attackerGroup.position.z = base.z + dz * (1 - p);
643:       attackerGroup.rotation.z = dir * 0.06 * (1 - p);
644:     });
645:   }
646: 
647:   damage(attacker, defender, move) {
648:     const atk = attacker.atk * stageMultiplier(attacker.atkStage);
649:     const def = defender.def * stageMultiplier(defender.defStage);
650:     const eff = typeMultiplier(move.type, SPECIES[defender.species].type);
651:     const stab = move.type === SPECIES[attacker.species].type ? 1.2 : 1;
652:     const crit = Math.random() < 0.07;
653:     let dmg = ((2 * attacker.level / 5 + 2) * move.power * atk / def) / 50 + 2;
654:     dmg = dmg * eff * stab * (crit ? 1.5 : 1) * (0.86 + Math.random() * 0.28);
655:     return { dmg: Math.max(1, Math.round(dmg)), eff, crit };
656:   }
657: 
658:   chooseEnemyMove() {
659:     const enemy = this.enemy;
660:     const available = enemy.moves.filter((m) => m.pp > 0);
661:     if (!available.length) return MOVES.tackle;
662:     const scored = available.map((entry) => {
