849:   spawnMelody(flute) {
850:     const texture = getNoteTexture();
851:     const group = new THREE.Group();
852:     this.scene.add(group);
853:     const material = new THREE.SpriteMaterial({
854:       map: texture, color: flute.color, transparent: true, opacity: 0.95,
855:       depthWrite: false, depthTest: false,
856:     });
857:     const sprites = [];
858:     const start = this.playerGroup
859:       ? this.playerGroup.position.clone().add(new THREE.Vector3(0.2, 1.5, 0.3))
860:       : new THREE.Vector3(3.1, 2, 2.7);
861:     const end = this.enemyGroup
862:       ? this.enemyGroup.position.clone().add(new THREE.Vector3(0, 1.3, 0))
863:       : new THREE.Vector3(-3.1, 1.8, -2.6);
864:     const mid = start.clone().lerp(end, 0.5).add(new THREE.Vector3(0, 2.8, 0));
865:     for (let i = 0; i < 7; i++) {
866:       const sprite = new THREE.Sprite(material);
867:       sprite.position.copy(start);
868:       sprite.scale.setScalar(0.34 + (i % 3) * 0.06);
869:       group.add(sprite);
870:       sprites.push(sprite);
871:     }
872:     // expanding resonance ring at the player's feet
873:     const ring = new THREE.Mesh(
874:       new THREE.RingGeometry(0.8, 1.0, 40),
875:       new THREE.MeshBasicMaterial({ color: flute.color, transparent: true, opacity: 0.6, side: THREE.DoubleSide, depthWrite: false }),
876:     );
877:     ring.rotation.x = -Math.PI / 2;
878:     ring.position.copy(this.playerGroup ? this.playerGroup.position : new THREE.Vector3(3.1, 0.6, 2.7));
879:     ring.position.y += 0.12;
880:     this.scene.add(ring);
881:     const ringTween = this.tween(1200, (p) => {
882:       ring.scale.setScalar(0.4 + p * 3.2);
883:       ring.material.opacity = 0.6 * (1 - p);
884:     }, (t) => t);
885: 
886:     const noteTween = this.tween(1650, (p) => {
887:       sprites.forEach((sprite, i) => {
888:         const delay = i * 0.085;
889:         const u = Math.min(1, Math.max(0, (p - delay) / (1 - delay)));
890:         const a = (1 - u) * (1 - u);
891:         const b = 2 * (1 - u) * u;
892:         const c = u * u;
893:         sprite.position.set(
894:           start.x * a + mid.x * b + end.x * c,
895:           start.y * a + mid.y * b + end.y * c + Math.sin(u * Math.PI) * 0.4,
896:           start.z * a + mid.z * b + end.z * c,
897:         );
898:         sprite.position.x += Math.sin(u * Math.PI * 2 + i) * 0.35;
899:         sprite.material.opacity = 0.95 * (1 - Math.max(0, u - 0.75) * 3.2);
900:         sprite.scale.setScalar(0.26 + Math.sin(u * Math.PI) * 0.22);
901:       });
902:     }, (t) => t);
903: 
904:     return Promise.all([noteTween, ringTween]).then(() => {
905:       this.scene.remove(group);
906:       this.scene.remove(ring);
907:       material.dispose();
908:       ring.geometry.dispose();
909:       ring.material.dispose();
910:     });
911:   }
