583: export function buildCreature(speciesId, appearance = null) {
584:   if (speciesId && typeof speciesId === 'object') {
585:     appearance = speciesId.appearance || null;
586:     speciesId = speciesId.species;
587:   }
588:   const builder = BUILDERS[speciesId] || buildSpriglet;
589:   const g = builder();
590:   g.traverse((o) => {
591:     if (o.isMesh) {
592:       o.castShadow = true;
593:       o.receiveShadow = true;
594:     }
595:   });
596:   if (speciesId === 'elderwood') {
597:     g.scale.setScalar(1.15);
598:   }
599:   if (appearance?.shiny && appearance.seed) applyShiny(g, appearance.seed);
600:   g.userData.speciesId = speciesId;
601:   return g;
602: }
