604: export function animateCreature(g, time, excitement = 0) {
605:   const a = g.userData.anim;
606:   if (!a) return;
607:   const speed = 2.3 + excitement;
608:   const breathe = Math.sin(time * speed) * 0.025;
609:   if (a.body) a.body.position.y = (a.bodyY || 0) + breathe;
610:   if (a.head) {
611:     a.head.rotation.z = Math.sin(time * speed * 0.7) * 0.045;
612:     a.head.rotation.x = Math.cos(time * speed * 0.43) * 0.025;
613:   }
614:   if (a.ears) {
615:     a.ears.forEach((ear, i) => {
616:       ear.rotation.x = Math.sin(time * speed * 1.25 + i) * 0.1;
617:     });
618:   }
619:   if (a.tail) {
620:     a.tail.forEach((tail, i) => {
621:       tail.rotation.y = Math.sin(time * speed * 0.9 + i * 0.8) * 0.16;
622:       tail.rotation.x = Math.sin(time * speed * 0.5 + i) * 0.05;
623:     });
624:   }
625:   if (a.wings) {
626:     a.wings.forEach((wing, i) => {
627:       wing.rotation.z = (i === 0 ? 1 : -1) * (0.18 + Math.sin(time * speed * 2.2) * 0.35);
628:     });
629:   }
630:   if (a.arms) {
631:     a.arms.forEach((arm, i) => {
632:       arm.position.y = 0.56 + Math.sin(time * speed * 0.8 + i) * 0.03;
633:     });
634:   }
635:   if (a.glow) {
636:     a.glow.forEach((orb, i) => {
637:       if (orb.material && orb.material.emissiveIntensity !== undefined) {
638:         orb.material.emissiveIntensity = 1.8 + Math.sin(time * 2 + i) * 0.7;
639:       }
640:       orb.position.y += Math.sin(time * 1.7 + i) * 0.0007;
641:     });
642:   }
643:   if (a.halo) {
644:     a.halo.rotation.z = time * 0.7;
645:     a.halo.rotation.y = Math.sin(time * 0.8) * 0.2;
646:   }
647:   if (a.leaf) {
648:     a.leaf.rotation.z = -0.5 + Math.sin(time * 1.8) * 0.12;
649:   }
650:   animateShiny(a, time);
651: }
