636:     a.glow.forEach((orb, i) => {
637:       if (orb.material && orb.material.emissiveIntensity !== undefined) {
638:         orb.material.emissiveIntensity = 1.8 + Math.sin(time * 2 + i) * 0.7;
639:       }
