    ctx.lineTo(mx + nx * side * 0.35, my + ny * side * 0.35);
    ctx.lineTo(mx, my);
    ctx.closePath();
    ctx.fillStyle = i % 3 === 0 ? base : edge;
    ctx.fill();
    ctx.strokeStyle = INK;
    ctx.lineWidth = 2;
    ctx.stroke();
  }
  ctx.restore();
}

